import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';

const GEMINI_BASE_URL = 'https://generativelanguage.googleapis.com/v1beta';
const MODEL = 'gemini-2.0-flash';
const MAX_OUTPUT_TOKENS = 4096;

const KNOWN_TEMPLATES = [
  'generic', 'ideal-gas-piston', 'sorting-bars', 'variable-binding-memory',
  'function-plot', 'pendulum', 'wave', 'projectile', 'pythagorean', 'unit-circle',
];

const SYSTEM_PROMPT = `You are an expert STEM education content designer. Your task is to generate a structured JSON specification for an interactive visual simulation block.

OUTPUT FORMAT:
Return ONLY a valid JSON object (no markdown, no code fences, no explanation). The JSON must follow this schema exactly:

{
  "version": "scene-v1",
  "templateFamily": "<one of the template IDs below>",
  "title": "<short title>",
  "description": "<one sentence description>",
  "runtime": {
    "mode": "<static|parametric|simulation>",
    "timeScale": 1.0,
    "solver": "euler",
    "autoplay": false
  },
  "teaching": {
    "focus": "<one sentence describing what the learner should observe>",
    "hints": ["<hint 1>", "<hint 2>"]
  },
  "initialState": { "<key>": <value> },
  "controls": [
    {
      "id": "<unique id>",
      "type": "<slider|button|toggle>",
      "label": "<display label>",
      "stateKey": "<key in initialState>",
      "min": <number>,
      "max": <number>,
      "step": <number>,
      "defaultValue": <value>,
      "unit": "<optional unit string>",
      "action": "<play|pause|reset|step|randomize — for buttons only>"
    }
  ],
  "formulas": [
    { "id": "f1", "expression": "<math expression>", "description": "<optional>" }
  ],
  "scene": { "<template-specific keys>": <values> },
  "layoutPreset": "split",
  "themeTone": "light-science",
  "generationMeta": {
    "templateChoice": "<templateFamily value>",
    "confidence": <0.0-1.0>,
    "warnings": []
  }
}

TEMPLATE GUIDE — choose the templateFamily that best fits the concept:

- "generic": General visual scene with state display. Use when no specific template fits.
- "ideal-gas-piston": Physics — ideal gas law PV=nRT. runtime.mode="parametric". scene: {pistonHeightFraction, particleCount}. initialState: {P, V, n, T}.
- "sorting-bars": CS — sorting algorithm visualization. runtime.mode="static". scene: {algorithm: "bubble-sort", barCount: 9}. initialState: {values: [...], stepIndex: 0, comparing: [], swapped: [], sorted: []}.
- "variable-binding-memory": CS — variable to memory slot binding. runtime.mode="static". scene: {steps: [{code, varName, value, address}]}. initialState: {stepIndex: 0, variables: [], memory: []}.
- "function-plot": Math — plot a function with parameter sliders. runtime.mode="parametric". scene: {xMin, xMax, yMin, yMax, expression: "quadratic"}. initialState: {a, b, c}.
- "pendulum": Physics — simple pendulum. runtime.mode="simulation", autoplay=true. initialState: {length, gravity, angle0}.
- "wave": Physics — traveling sine wave. runtime.mode="simulation", autoplay=true. initialState: {amplitude, frequency, speed}.
- "projectile": Physics — projectile motion. runtime.mode="simulation", autoplay=false. initialState: {angle, velocity, gravity}.
- "pythagorean": Math — Pythagorean theorem right triangle. runtime.mode="parametric". initialState: {a, b}.
- "unit-circle": Math — unit circle sin/cos. runtime.mode="parametric". initialState: {angle}.

SELECTION RULES:
1. Match the STEM concept to the closest template.
2. If the concept is CS/algorithms → prefer sorting-bars or variable-binding-memory.
3. If the concept involves physical motion → prefer pendulum, wave, or projectile (simulation).
4. If the concept is a formula with parameters → prefer parametric templates.
5. Only use "generic" if truly nothing fits.

IMPORTANT:
- Output ONLY the JSON object, nothing else.
- All required fields must be present.
- "generationMeta.confidence" should reflect how well the template matches (0.8+ = good match, 0.5-0.8 = acceptable, <0.5 = generic fallback with warning).`;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface SpecJson {
  version: string;
  templateFamily: string;
  runtime?: { mode: string; [key: string]: unknown };
  controls?: unknown[];
  [key: string]: unknown;
}

function validateSpec(obj: unknown): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (typeof obj !== 'object' || obj === null) {
    errors.push('Spec must be a JSON object');
    return { valid: false, errors };
  }
  const spec = obj as Record<string, unknown>;

  if (spec['version'] !== 'scene-v1') {
    errors.push(`version must be "scene-v1", got "${spec['version']}"`);
  }
  if (!spec['templateFamily'] || !KNOWN_TEMPLATES.includes(spec['templateFamily'] as string)) {
    errors.push(`templateFamily must be one of: ${KNOWN_TEMPLATES.join(', ')}. Got: "${spec['templateFamily']}"`);
  }
  const runtime = spec['runtime'] as Record<string, unknown> | undefined;
  if (!runtime || typeof runtime !== 'object') {
    errors.push('runtime object is required');
  } else {
    const validModes = ['static', 'parametric', 'simulation'];
    if (!validModes.includes(runtime['mode'] as string)) {
      errors.push(`runtime.mode must be one of: ${validModes.join(', ')}. Got: "${runtime['mode']}"`);
    }
  }
  if (spec['controls'] !== undefined && !Array.isArray(spec['controls'])) {
    errors.push('controls must be an array');
  }

  return { valid: errors.length === 0, errors };
}

function stripCodeFences(text: string): string {
  // Remove ```json ... ``` or ``` ... ``` wrappers
  const match = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) return match[1].trim();
  return text.trim();
}

async function callGemini(
  geminiUrl: string,
  messages: Array<{ role: string; parts: Array<{ text: string }> }>,
): Promise<string> {
  const body = {
    system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
    contents: messages,
    generationConfig: {
      temperature: 0.4,
      maxOutputTokens: MAX_OUTPUT_TOKENS,
    },
  };
  const res = await fetch(geminiUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Gemini API error ${res.status}: ${errText}`);
  }
  const data = await res.json();
  return data?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { prompt } = await req.json();
    if (!prompt || typeof prompt !== 'string' || prompt.trim().length === 0) {
      return new Response(
        JSON.stringify({ error: 'prompt is required' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const geminiApiKey = Deno.env.get('GEMINI_API_KEY');
    if (!geminiApiKey) {
      return new Response(
        JSON.stringify({ error: 'Platform AI service not configured' }),
        { status: 503, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const geminiUrl = `${GEMINI_BASE_URL}/models/${MODEL}:generateContent?key=${geminiApiKey}`;
    const messages: Array<{ role: string; parts: Array<{ text: string }> }> = [
      { role: 'user', parts: [{ text: prompt.trim() }] },
    ];

    // First attempt
    let rawText = await callGemini(geminiUrl, messages);
    if (!rawText.trim()) {
      return new Response(
        JSON.stringify({ error: 'AI returned empty response' }),
        { status: 502, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    let specObj: unknown;
    try {
      specObj = JSON.parse(stripCodeFences(rawText));
    } catch {
      specObj = null;
    }

    let validation = validateSpec(specObj);

    // Repair loop: one retry on validation failure
    if (!validation.valid) {
      console.warn('[gemini-generate] Validation failed, attempting repair:', validation.errors);
      const repairPrompt = `Your previous response had validation errors:\n${validation.errors.join('\n')}\n\nPrevious response:\n${rawText}\n\nPlease fix the issues and return a valid JSON spec that passes all validation rules. Return ONLY the JSON object.`;
      messages.push({ role: 'model', parts: [{ text: rawText }] });
      messages.push({ role: 'user', parts: [{ text: repairPrompt }] });

      rawText = await callGemini(geminiUrl, messages);
      try {
        specObj = JSON.parse(stripCodeFences(rawText));
      } catch {
        specObj = null;
      }
      validation = validateSpec(specObj);
    }

    if (!validation.valid) {
      console.error('[gemini-generate] Spec still invalid after repair:', validation.errors);
      return new Response(
        JSON.stringify({
          error: `Generated spec failed validation: ${validation.errors.join('; ')}`,
          rawText,
        }),
        { status: 422, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    return new Response(
      JSON.stringify({ spec: specObj as SpecJson }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (err) {
    console.error('[gemini-generate] Unexpected error:', err);
    return new Response(
      JSON.stringify({ error: String(err) }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});

