     1→/// InteractiveVisualContent — unified visual simulation block model.
     2→/// Replaces the legacy AnimationContent as the canonical visual block.
     3→/// This is a part of block.dart's library so it can implement BlockContent
     4→/// without a circular import.
     5→part of 'block.dart';
     6→
     7→/// Modes for interactive-visual blocks
     8→class VisualMode {
     9→  static const String presentation = 'presentation';
    10→  static const String interactive = 'interactive';
    11→  static const String guided = 'guided';
    12→  static const String assessment = 'assessment';
    13→  static const Set<String> all = {
    14→    presentation,
    15→    interactive,
    16→    guided,
    17→    assessment,
    18→  };
    19→}
    20→
    21→/// Layout preset
    22→class VisualLayoutPreset {
    23→  static const String split = 'split'; // controls left/right + scene
    24→  static const String stack = 'stack'; // controls top/bottom + scene
    25→  static const String sceneOnly = 'scene-only'; // just the scene
    26→  static const Set<String> all = {split, stack, sceneOnly};
    27→}
    28→
    29→/// Theme tone
    30→class VisualThemeTone {
    31→  static const String lightScience = 'light-science';
    32→  static const String chalk = 'chalk';
    33→  static const String lab = 'lab';
    34→  static const Set<String> all = {lightScience, chalk, lab};
    35→}
    36→
    37→/// A visual control descriptor (slider, button, toggle, etc.)
    38→class VisualControl {
    39→  static const String typeSlider = 'slider';
    40→  static const String typeButton = 'button';
    41→  static const String typeToggle = 'toggle';
    42→  static const String typeStepper = 'stepper';
    43→  static const String typeDropdown = 'dropdown';
    44→
    45→  final String id;
    46→  final String type;
    47→  final String label;
    48→  final String? stateKey; // which state key this control drives
    49→  final double? min;
    50→  final double? max;
    51→  final double? step;
    52→  final dynamic defaultValue;
    53→  final List<String>? options; // for dropdown
    54→  final String? action; // for button: 'play'|'pause'|'reset'|'step'|'check'|'randomize'
    55→  final String? unit; // e.g. 'K', 'atm', 'm³'
    56→
    57→  const VisualControl({
    58→    required this.id,
    59→    required this.type,
    60→    required this.label,
    61→    this.stateKey,
    62→    this.min,
    63→    this.max,
    64→    this.step,
    65→    this.defaultValue,
    66→    this.options,
    67→    this.action,
    68→    this.unit,
    69→  });
    70→
    71→  factory VisualControl.fromJson(Map<String, dynamic> json) {
    72→    return VisualControl(
    73→      id: json['id'] as String? ?? '',
    74→      type: json['type'] as String? ?? typeSlider,
    75→      label: json['label'] as String? ?? '',
    76→      stateKey: json['stateKey'] as String?,
    77→      min: (json['min'] as num?)?.toDouble(),
    78→      max: (json['max'] as num?)?.toDouble(),
    79→      step: (json['step'] as num?)?.toDouble(),
    80→      defaultValue: json['defaultValue'],
    81→      options: (json['options'] as List<dynamic>?)?.cast<String>(),
    82→      action: json['action'] as String?,
    83→      unit: json['unit'] as String?,
    84→    );
    85→  }
    86→
    87→  Map<String, dynamic> toJson() {
    88→    final m = <String, dynamic>{'id': id, 'type': type, 'label': label};
    89→    if (stateKey != null) m['stateKey'] = stateKey;
    90→    if (min != null) m['min'] = min;
    91→    if (max != null) m['max'] = max;
    92→    if (step != null) m['step'] = step;
    93→    if (defaultValue != null) m['defaultValue'] = defaultValue;
    94→    if (options != null) m['options'] = options;
    95→    if (action != null) m['action'] = action;
    96→    if (unit != null) m['unit'] = unit;
    97→    return m;
    98→  }
    99→}
   100→
   101→/// A formula descriptor for display
   102→class VisualFormula {
   103→  final String id;
   104→  final String expression; // e.g. 'PV = nRT'
   105→  final String? description;
   106→  final Map<String, String>? variableLabels; // e.g. {'P': 'Pressure', 'V': 'Volume'}
   107→
   108→  const VisualFormula({
   109→    required this.id,
   110→    required this.expression,
   111→    this.description,
   112→    this.variableLabels,
   113→  });
   114→
   115→  factory VisualFormula.fromJson(Map<String, dynamic> json) {
   116→    final rawLabels = json['variableLabels'];
   117→    return VisualFormula(
   118→      id: json['id'] as String? ?? '',
   119→      expression: json['expression'] as String? ?? '',
   120→      description: json['description'] as String?,
   121→      variableLabels:
   122→          rawLabels is Map
   123→              ? Map<String, String>.from(
   124→                rawLabels.map((k, v) => MapEntry(k.toString(), v.toString())),
   125→              )
   126→              : null,
   127→    );
   128→  }
   129→
   130→  Map<String, dynamic> toJson() {
   131→    final m = <String, dynamic>{'id': id, 'expression': expression};
   132→    if (description != null) m['description'] = description;
   133→    if (variableLabels != null) m['variableLabels'] = variableLabels;
   134→    return m;
   135→  }
   136→}
   137→
   138→/// A check predicate for assessment mode
   139→class VisualCheck {
   140→  final String id;
   141→  final String description;
   142→  final String stateKey;
   143→  final String operator; // 'eq'|'gt'|'lt'|'gte'|'lte'|'range'
   144→  final dynamic target;
   145→  final dynamic targetMax; // for 'range'
   146→  final String? feedbackCorrect;
   147→  final String? feedbackIncorrect;
   148→
   149→  const VisualCheck({
   150→    required this.id,
   151→    required this.description,
   152→    required this.stateKey,
   153→    required this.operator,
   154→    required this.target,
   155→    this.targetMax,
   156→    this.feedbackCorrect,
   157→    this.feedbackIncorrect,
   158→  });
   159→
   160→  factory VisualCheck.fromJson(Map<String, dynamic> json) {
   161→    return VisualCheck(
   162→      id: json['id'] as String? ?? '',
   163→      description: json['description'] as String? ?? '',
   164→      stateKey: json['stateKey'] as String? ?? '',
   165→      operator: json['operator'] as String? ?? 'eq',
   166→      target: json['target'],
   167→      targetMax: json['targetMax'],
   168→      feedbackCorrect: json['feedbackCorrect'] as String?,
   169→      feedbackIncorrect: json['feedbackIncorrect'] as String?,
   170→    );
   171→  }
   172→
   173→  Map<String, dynamic> toJson() {
   174→    final m = <String, dynamic>{
   175→      'id': id,
   176→      'description': description,
   177→      'stateKey': stateKey,
   178→      'operator': operator,
   179→      'target': target,
   180→    };
   181→    if (targetMax != null) m['targetMax'] = targetMax;
   182→    if (feedbackCorrect != null) m['feedbackCorrect'] = feedbackCorrect;
   183→    if (feedbackIncorrect != null) m['feedbackIncorrect'] = feedbackIncorrect;
   184→    return m;
   185→  }
   186→
   187→  /// Evaluate this check against a given state map
   188→  bool evaluate(Map<String, dynamic> state) {
   189→    final value = state[stateKey];
   190→    if (value == null) return false;
   191→    final num? v =
   192→        value is num ? value : num.tryParse(value.toString());
   193→    final num? t =
   194→        target is num
   195→            ? target as num
   196→            : num.tryParse(target?.toString() ?? '');
   197→    if (v == null || t == null) return value.toString() == target?.toString();
   198→    switch (operator) {
   199→      case 'eq':
   200→        return (v - t).abs() < 0.001;
   201→      case 'gt':
   202→        return v > t;
   203→      case 'lt':
   204→        return v < t;
   205→      case 'gte':
   206→        return v >= t;
   207→      case 'lte':
   208→        return v <= t;
   209→      case 'range':
   210→        final num? tMax =
   211→            targetMax is num
   212→                ? targetMax as num
   213→                : num.tryParse(targetMax?.toString() ?? '');
   214→        return tMax != null && v >= t && v <= tMax;
   215→      default:
   216→        return false;
