<!DOCTYPE html>
<html>
<head>
<title>Simple Pendulum</title>
<style>
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #1a1a2e;
}
canvas {
  display: block;
}
#controls {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
}
#controls button {
  background-color: #394a6a;
  color: white;
  border: none;
  padding: 5px 10px;
  cursor: pointer;
  border-radius: 5px;
}
#controls button:hover {
  background-color: #4a648c;
}
</style>
</head>
<body>
<canvas id="pendulumCanvas"></canvas>
<div id="controls">
  <button id="toggleButton">Pause</button>
</div>
<script>
const canvas = document.getElementById('pendulumCanvas');
const ctx = canvas.getContext('2d');
const toggleButton = document.getElementById('toggleButton');

let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width;
canvas.height = height;

let angle = Math.PI / 4; // Initial angle (45 degrees)
let angularVelocity = 0;
let angularAcceleration = 0;
const gravity = 0.98; // Simulated gravity
const stringLength = height / 3; // Length of the pendulum string
const bobRadius = 20; // Radius of the pendulum bob
let damping = 0.005; // Damping force to slow down the pendulum

let isPaused = false;

toggleButton.addEventListener('click', () => {
    isPaused = !isPaused;
    toggleButton.textContent = isPaused ? "Resume" : "Pause";
});

function updatePendulum() {
    if (!isPaused) {
        angularAcceleration = (-gravity / stringLength) * Math.sin(angle);
        angularVelocity += angularAcceleration;
        angularVelocity *= (1 - damping); // Apply damping
        angle += angularVelocity;
    }
}

function drawPendulum() {
  ctx.clearRect(0, 0, width, height);

  // Calculate bob position
  const x = width / 2 + stringLength * Math.sin(angle);
  const y = height / 4 + stringLength * Math.cos(angle);

  // Draw the string
  ctx.beginPath();
  ctx.moveTo(width / 2, height / 4);
  ctx.lineTo(x, y);
  ctx.strokeStyle = '#eee';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw the pendulum bob
  ctx.beginPath();
  ctx.arc(x, y, bobRadius, 0, 2 * Math.PI);
  ctx.fillStyle = '#eee';
  ctx.fill();
  ctx.strokeStyle = '#ccc';
  ctx.stroke();

  //Draw anchor point
  ctx.beginPath();
  ctx.arc(width / 2, height / 4, 5, 0, 2 * Math.PI);
  ctx.fillStyle = '#eee';
  ctx.fill();

  // Display angle (in degrees)
  ctx.font = "14px sans-serif";
  ctx.fillStyle = "#eee";
  const angleDegrees = (angle * 180 / Math.PI).toFixed(1);
  ctx.fillText(`Angle: ${angleDegrees}°`, 20, 30);

  // Display potential and kinetic energy (simplified)
  const potentialEnergy = (1 - Math.cos(angle)) * gravity * stringLength;
  const kineticEnergy = 0.5 * stringLength * stringLength * angularVelocity * angularVelocity;

  ctx.fillText(`Potential Energy: ${potentialEnergy.toFixed(2)}`, 20, 50);
  ctx.fillText(`Kinetic Energy: ${kineticEnergy.toFixed(2)}`, 20, 70);

}

function animate() {
  updatePendulum();
  drawPendulum();
  requestAnimationFrame(animate);
}

function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;
    // Reset initial angle and other parameters if necessary
}

window.addEventListener('resize', resizeCanvas);

animate(); // Start the animation loop

</script>
</body>
</html>
```"}

