              Expanded(
                child: Text(
                  content.title.isNotEmpty ? content.title : 'Interactive Visual',
                  style: const TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w600,
                    color: AppColors.neutral800,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: AppSpacing.sm),
