import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class UnitCircleRenderer extends VisualTemplateRenderer {
  const UnitCircleRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  /// Simulation step: increment angle
  static void simulationStep(Map<String, dynamic> state, double dt) {
    final angle = (state['angle'] as num?)?.toDouble() ?? 0.0;
    state['angle'] = (angle + dt * 60) % 360;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final angleDeg = (state['angle'] as num?)?.toDouble() ?? 45.0;
    final angleRad = angleDeg * math.pi / 180;
    final cosVal = math.cos(angleRad);
    final sinVal = math.sin(angleRad);

    final cx = size.width / 2;
    final cy = size.height / 2;
    final radius = math.min(cx, cy) * 0.75;

    // Draw axes
    final axisPaint = Paint()..color = axisColor..strokeWidth = 1.0;
    canvas.drawLine(Offset(cx - radius - 15, cy), Offset(cx + radius + 15, cy), axisPaint);
    canvas.drawLine(Offset(cx, cy - radius - 15), Offset(cx, cy + radius + 15), axisPaint);

    // Draw unit circle
    final circlePaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    canvas.drawCircle(Offset(cx, cy), radius, circlePaint);

    // Draw radius line
    final px = cx + cosVal * radius;
    final py = cy - sinVal * radius; // y flipped
    final radiusPaint = Paint()..color = primaryColor..strokeWidth = 2.0;
    canvas.drawLine(Offset(cx, cy), Offset(px, py), radiusPaint);

    // Point on circle
    canvas.drawCircle(Offset(px, py), 5, Paint()..color = primaryColor);

    // cos projection (horizontal)
    final cosPaint = Paint()..color = accentColor..strokeWidth = 1.5..style = PaintingStyle.stroke;
    final cosPath = Path()
      ..moveTo(px, py)
      ..lineTo(px, cy);
    canvas.drawPath(cosPath, cosPaint..strokeWidth = 1.5);
    canvas.drawLine(Offset(cx, cy), Offset(px, cy), Paint()..color = accentColor..strokeWidth = 2.0);

    // sin projection (vertical)
    final sinPaint = Paint()..color = successColor..strokeWidth = 2.0;
    canvas.drawLine(Offset(cx, cy), Offset(cx, py), sinPaint);

    // Labels
    _drawLabel(canvas, 'cos θ = ${cosVal.toStringAsFixed(2)}', Offset(4, size.height - 32), accentColor);
    _drawLabel(canvas, 'sin θ = ${sinVal.toStringAsFixed(2)}', Offset(4, size.height - 18), successColor);
    _drawLabel(canvas, '${angleDeg.toStringAsFixed(0)}°', Offset(cx + 8, cy + 8), textColor);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(
          text: text,
          style: TextStyle(
              color: color, fontSize: 10, fontWeight: FontWeight.w600)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(UnitCircleRenderer old) =>
      old.state['angle'] != state['angle'];
}

