import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class SortingBarsRenderer extends VisualTemplateRenderer {
  const SortingBarsRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final values = (state['values'] as List?)?.cast<int>() ?? [5, 3, 8, 1, 9, 2, 7, 4, 6];
    final comparing = (state['comparing'] as List?)?.cast<int>() ?? [];
    final swapped = (state['swapped'] as List?)?.cast<int>() ?? [];
    final sorted = (state['sorted'] as List?)?.cast<int>() ?? [];
    if (values.isEmpty) return;
    final n = values.length;
    final maxVal = values.reduce(math.max);
    final barWidth = (size.width - (n + 1) * 4.0) / n;
    final maxBarHeight = size.height - 30;
    for (int i = 0; i < n; i++) {
      final barH = (values[i] / maxVal) * maxBarHeight;
      final x = 4.0 + i * (barWidth + 4);
      final y = size.height - barH - 20;
      Color color;
      if (sorted.contains(i)) {
        color = successColor;
      } else if (swapped.contains(i)) {
        color = errorColor;
      } else if (comparing.contains(i)) {
        color = accentColor;
      } else {
        color = primaryColor;
      }
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, y, barWidth, barH),
          const Radius.circular(3),
        ),
        Paint()..color = color,
      );
      final tp = TextPainter(
        text: TextSpan(
          text: '${values[i]}',
          style: TextStyle(color: labelColor, fontSize: 9),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(x + barWidth / 2 - tp.width / 2, size.height - 18));
    }
  }

  @override
  bool shouldRepaint(SortingBarsRenderer old) =>
      old.state['values'] != state['values'] ||
      old.state['comparing'] != state['comparing'] ||
      old.state['swapped'] != state['swapped'] ||
      old.state['sorted'] != state['sorted'];

  /// Perform one bubble sort step, mutating [state].
  static void performStep(Map<String, dynamic> state) {
    final vals = List<int>.from(state['values'] as List? ?? []);
    final n = vals.length;
    int si = state['stepIndex'] as int? ?? 0;
    final stepsPerPass = n - 1;
    final pass = si ~/ stepsPerPass;
    final idx = si % stepsPerPass;
    if (pass >= n - 1) {
      state['comparing'] = <int>[];
      state['swapped'] = <int>[];
      state['sorted'] = List.generate(n, (i) => i);
      return;
    }
    final comparing = [idx, idx + 1];
    List<int> swapped = [];
    if (vals[idx] > vals[idx + 1]) {
      final tmp = vals[idx];
      vals[idx] = vals[idx + 1];
      vals[idx + 1] = tmp;
      swapped = [idx, idx + 1];
    }
    state['values'] = vals;
    state['stepIndex'] = si + 1;
    state['comparing'] = comparing;
    state['swapped'] = swapped;
    state['sorted'] = List.generate(pass, (i) => n - 1 - i);
  }
}

