/// Runtime widget for interactive-visual blocks.
/// Renders the actual simulation using template-specific CustomPainter renderers,
/// or an empty-state prompt if no spec has been generated yet.
library;

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../../models/block.dart' show InteractiveVisualContent, VisualControl;
import '../../services/visual_template_registry.dart';
import '../../theme/design_tokens.dart';
import 'interactive_visual/runtime_controller.dart';
import 'interactive_visual/visual_renderer_factory.dart';
import 'interactive_visual/renderers/sorting_bars_renderer.dart';

// Templates that have a custom CustomPainter renderer.
const _renderableTemplates = {
  'sorting-bars',
  'function-plot',
  'unit-circle',
  'ideal-gas-piston',
  'projectile',
};

class InteractiveVisualWidget extends StatefulWidget {
  final InteractiveVisualContent content;
  final bool isPreview;
  final double? forcedHeight;

  const InteractiveVisualWidget({
    super.key,
    required this.content,
    this.isPreview = false,
    this.forcedHeight,
  });

  @override
  State<InteractiveVisualWidget> createState() => _InteractiveVisualWidgetState();
}

class _InteractiveVisualWidgetState extends State<InteractiveVisualWidget>
    with TickerProviderStateMixin {
  RuntimeController? _controller;

  @override
  void initState() {
    super.initState();
    _initController();
  }

  @override
  void didUpdateWidget(InteractiveVisualWidget old) {
    super.didUpdateWidget(old);
    // Re-init when AI generates a new spec (aiPrompt or template changes).
    if (old.content.aiPrompt != widget.content.aiPrompt ||
        old.content.template != widget.content.template) {
      _controller?.dispose();
      _initController();
    }
  }

  void _initController() {
    final content = widget.content;
    final runtimeMode = content.runtime?.mode ?? 'static';
    _controller = RuntimeController(
      mode: runtimeMode,
      initialState: Map<String, dynamic>.from(content.initialState),
    );
    _controller!.simulationStep =
        VisualRendererFactory.simulationStepFor(content.template);
    _controller!.attach(this);
    // Builder preview: don't autoplay — let the user click Play.
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  void _handleAction(String action) {
    final ctrl = _controller;
    final template = widget.content.template;
    if (ctrl == null) return;

    switch (action) {
      case 'reset':
        ctrl.reset();
      case 'step':
        if (template == 'sorting-bars') ctrl.step(SortingBarsRenderer.performStep);
      case 'randomize':
        final rng = math.Random();
        final n = (widget.content.scene['barCount'] as int?) ?? 9;
        final newValues = List.generate(n, (_) => rng.nextInt(n) + 1);
        ctrl.reset();
        ctrl.updateParam('values', newValues);
      case 'play':
        final playHandler = VisualRendererFactory.playHandlerFor(template);
        if (playHandler != null) ctrl.step(playHandler);
        ctrl.play();
      case 'pause':
        ctrl.pause();
    }
  }

  @override
  Widget build(BuildContext context) {
    final height = widget.forcedHeight ?? 320.0;
    final hasSpec =
        widget.content.controls.isNotEmpty || widget.content.scene.isNotEmpty;

    if (!hasSpec) return _buildEmptyState(height);

    final content = widget.content;
    final template = content.template;
    final isDark = content.themeTone == 'chalk' || content.themeTone == 'lab';
    final bg = isDark ? const Color(0xFF0D1117) : const Color(0xFFF0F6FF);
    final borderColor =
        isDark ? const Color(0xFF30363D) : AppColors.neutral200;
    final runtimeMode = content.runtime?.mode ?? 'static';
    final isSimulation = runtimeMode == 'simulation';
    final isParametric = runtimeMode == 'parametric';
    final showControls =
        isSimulation || isParametric || template == 'sorting-bars';
    final templateLabel =
        VisualTemplateRegistry.labels[template] ?? template;

    return Container(
      height: height,
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(AppBorderRadius.lg),
        border: Border.all(color: borderColor),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        children: [
          // ── Header ──────────────────────────────────────────────────────
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: Row(
              children: [
                _Badge(
                  label: templateLabel,
                  color: AppColors.primary100,
                  textColor: AppColors.primary700,
                ),
                const SizedBox(width: 6),
                _Badge(
                  label: runtimeMode,
                  color: AppColors.neutral100,
                  textColor: AppColors.neutral600,
                ),
                if (content.title.isNotEmpty) ...[
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      content.title,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                        color: isDark
                            ? const Color(0xFFE6EDF3)
                            : AppColors.neutral700,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ],
              ],
            ),
          ),
          // ── Formula bar ─────────────────────────────────────────────────
          if (content.formulas.isNotEmpty)
            Container(
              padding:
                  const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
              decoration: BoxDecoration(
                border: Border(
                  bottom: BorderSide(
                    color: isDark
                        ? const Color(0xFF30363D)
                        : AppColors.neutral200,
                  ),
                ),
              ),
              child: Wrap(
                spacing: 16,
                children: content.formulas
                    .map((f) => Text(
                          f.expression,
                          style: TextStyle(
                            fontFamily: 'monospace',
                            fontSize: 12,
                            fontWeight: FontWeight.w600,
                            color: isDark
                                ? const Color(0xFF58A6FF)
                                : AppColors.primary600,
                          ),
                        ))
                    .toList(),
              ),
            ),
          // ── Scene canvas ─────────────────────────────────────────────────
          Expanded(child: _buildScene(template, isDark, bg)),
          // ── Control bar ──────────────────────────────────────────────────
          if (showControls)
            _buildControlBar(
                content, isDark, isSimulation, isParametric, template),
        ],
      ),
    );
  }

  Widget _buildScene(String template, bool isDark, Color bg) {
    final ctrl = _controller;
    if (ctrl != null && _renderableTemplates.contains(template)) {
      return Container(
        color: bg,
        child: ListenableBuilder(
          listenable: ctrl,
          builder: (context, _) {
            final painter = VisualRendererFactory.create(
              templateFamily: template,
              state: ctrl.state,
              scene: widget.content.scene,
              isDark: isDark,
            );
            return CustomPaint(painter: painter, size: Size.infinite);
          },
        ),
      );
    }
    return _buildGenericFallback(isDark, bg);
  }

  Widget _buildGenericFallback(bool isDark, Color bg) {
    final textColor =
        isDark ? const Color(0xFFE6EDF3) : AppColors.neutral800;
    final labelColor =
        isDark ? const Color(0xFF8B949E) : AppColors.neutral500;
    final state = widget.content.initialState;
    final publicState = {
      for (final e in state.entries)
        if (!e.key.startsWith('_')) e.key: e.value,
    };

    return Container(
      color: bg,
      padding: const EdgeInsets.all(12),
      child: publicState.isEmpty
          ? Center(
              child: Text(
                widget.content.title.isNotEmpty
                    ? widget.content.title
                    : 'Interactive Visual',
                style: TextStyle(fontSize: 15, color: textColor),
              ),
            )
          : Wrap(
              spacing: 16,
              runSpacing: 8,
              children: publicState.entries
                  .map(
                    (e) => Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(e.key,
                            style:
                                TextStyle(fontSize: 10, color: labelColor)),
                        Text(
                          e.value.toString(),
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                            color: isDark
                                ? const Color(0xFF58A6FF)
                                : AppColors.primary600,
                          ),
                        ),
                      ],
                    ),
                  )
                  .toList(),
            ),
    );
  }

  Widget _buildControlBar(
    InteractiveVisualContent content,
    bool isDark,
    bool isSimulation,
    bool isParametric,
    String template,
  ) {
    final ctrl = _controller;
    if (ctrl == null) return const SizedBox.shrink();

    final bgCtrl = isDark ? const Color(0xFF161B22) : Colors.white;
    final borderColor =
        isDark ? const Color(0xFF30363D) : AppColors.neutral200;
    final labelColor =
        isDark ? const Color(0xFF8B949E) : AppColors.neutral500;
    final textColor =
        isDark ? const Color(0xFFE6EDF3) : AppColors.neutral700;

    final sliders = content.controls
        .where((c) => c.type == VisualControl.typeSlider)
        .take(3)
        .toList();

    return Container(
      decoration: BoxDecoration(
        color: bgCtrl,
        border: Border(top: BorderSide(color: borderColor)),
      ),
      padding: const EdgeInsets.fromLTRB(12, 6, 12, 8),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Sliders (parametric or simulation with sliders)
          if ((isParametric || isSimulation) && sliders.isNotEmpty)
            ...sliders.map((c) => _buildSliderRow(
                c, ctrl, isDark, labelColor, textColor)),
          const SizedBox(height: 4),
          // Action buttons
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              if (isSimulation)
                ListenableBuilder(
                  listenable: ctrl,
                  builder: (context, _) {
                    final running = ctrl.isRunning;
                    return _ControlButton(
                      icon: running ? Icons.pause : Icons.play_arrow,
                      label: running ? 'Pause' : 'Play',
                      onTap: () =>
                          _handleAction(running ? 'pause' : 'play'),
                      isDark: isDark,
                    );
                  },
                ),
              if (isSimulation) const SizedBox(width: 8),
              if (template == 'sorting-bars') ...[
                _ControlButton(
                  icon: Icons.skip_next,
                  label: 'Step',
                  onTap: () => _handleAction('step'),
                  isDark: isDark,
                ),
                const SizedBox(width: 8),
                _ControlButton(
                  icon: Icons.shuffle,
                  label: 'Randomize',
                  onTap: () => _handleAction('randomize'),
                  isDark: isDark,
                ),
                const SizedBox(width: 8),
              ],
              _ControlButton(
                icon: Icons.restart_alt,
                label: 'Reset',
                onTap: () => _handleAction('reset'),
                isDark: isDark,
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildSliderRow(
    VisualControl ctrl,
    RuntimeController controller,
    bool isDark,
    Color labelColor,
    Color textColor,
  ) {
    final key = ctrl.stateKey ?? '';
    final min = ctrl.min ?? 0.0;
    final max = ctrl.max ?? 100.0;
    final defaultVal = (ctrl.defaultValue as num?)?.toDouble() ?? min;
    final unitStr = ctrl.unit != null ? ' (${ctrl.unit})' : '';

    return ListenableBuilder(
      listenable: controller,
      builder: (context, _) {
        final val = ((controller.state[key] as num?)?.toDouble() ?? defaultVal)
            .clamp(min, max);
        return Row(
          children: [
            SizedBox(
              width: 80,
              child: Text(
                '${ctrl.label}$unitStr',
                style: TextStyle(fontSize: 10, color: labelColor),
                overflow: TextOverflow.ellipsis,
              ),
            ),
            Expanded(
              child: SliderTheme(
                data: SliderTheme.of(context).copyWith(
                  trackHeight: 2,
                  thumbShape:
                      const RoundSliderThumbShape(enabledThumbRadius: 6),
                  overlayShape:
                      const RoundSliderOverlayShape(overlayRadius: 12),
                  activeTrackColor: AppColors.primary500,
                  inactiveTrackColor: isDark
                      ? const Color(0xFF30363D)
                      : AppColors.neutral300,
                  thumbColor: AppColors.primary500,
                  overlayColor: AppColors.primary500.withOpacity(0.2),
                ),
                child: Slider(
                  value: val,
                  min: min,
                  max: max,
                  onChanged: (v) => controller.updateParam(key, v),
                ),
              ),
            ),
            SizedBox(
              width: 36,
              child: Text(
                val.toStringAsFixed(1),
                style: TextStyle(
                  fontSize: 10,
                  color: textColor,
                  fontFamily: 'monospace',
                ),
                textAlign: TextAlign.end,
              ),
            ),
          ],
        );
      },
    );
  }

  Widget _buildEmptyState(double height) {
    return Container(
      height: height,
      decoration: BoxDecoration(
        color: const Color(0xFFF7F9FC),
        borderRadius: BorderRadius.circular(AppBorderRadius.lg),
        border: Border.all(color: AppColors.neutral200),
      ),
      child: const Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.auto_awesome, color: AppColors.neutral400, size: 28),
            SizedBox(height: AppSpacing.sm),
            Text(
              'Interactive Visual',
              style: TextStyle(
                fontSize: 13,
                fontWeight: FontWeight.w500,
                color: AppColors.neutral500,
              ),
            ),
            SizedBox(height: 4),
            Text(
              'Use AI Generation to create a simulation',
              style: TextStyle(fontSize: 11, color: AppColors.neutral400),
            ),
          ],
        ),
      ),
    );
  }
}

