    11→  });
    12→
    13→  @override
    14→  void paint(Canvas canvas, Size size) {
    15→    final values = (state['values'] as List?)?.cast<int>() ?? [5, 3, 8, 1, 9, 2, 7, 4, 6];
    16→    final comparing = (state['comparing'] as List?)?.cast<int>() ?? [];
    17→    final swapped = (state['swapped'] as List?)?.cast<int>() ?? [];
    18→    final sorted = (state['sorted'] as List?)?.cast<int>() ?? [];
    19→    if (values.isEmpty) return;
    20→    final n = values.length;
    21→    final maxVal = values.reduce(math.max);
    22→    final barWidth = (size.width - (n + 1) * 4.0) / n;
    23→    final maxBarHeight = size.height - 30;
    24→    for (int i = 0; i < n; i++) {
    25→      final barH = (values[i] / maxVal) * maxBarHeight;
    26→      final x = 4.0 + i * (barWidth + 4);
    27→      final y = size.height - barH - 20;
    28→      Color color;
    29→      if (sorted.contains(i)) {
    30→        color = successColor;
    31→      } else if (swapped.contains(i)) {
    32→        color = errorColor;
    33→      } else if (comparing.contains(i)) {
    34→        color = accentColor;
    35→      } else {
    36→        color = primaryColor;
    37→      }
    38→      canvas.drawRRect(
    39→        RRect.fromRectAndRadius(
    40→          Rect.fromLTWH(x, y, barWidth, barH),
    41→          const Radius.circular(3),
    42→        ),
    43→        Paint()..color = color,
    44→      );
    45→      final tp = TextPainter(
    46→        text: TextSpan(
    47→          text: '${values[i]}',
    48→          style: TextStyle(color: labelColor, fontSize: 9),
    49→        ),
    50→        textDirection: TextDirection.ltr,
    51→      )..layout();
    52→      tp.paint(canvas, Offset(x + barWidth / 2 - tp.width / 2, size.height - 18));
    53→    }
    54→  }
    55→
    56→  @override
    57→  bool shouldRepaint(SortingBarsRenderer old) =>
    58→      old.state['values'] != state['values'] ||
    59→      old.state['comparing'] != state['comparing'] ||
    60→      old.state['swapped'] != state['swapped'] ||
    61→      old.state['sorted'] != state['sorted'];
    62→
    63→  /// Perform one bubble sort step, mutating [state].
    64→  static void performStep(Map<String, dynamic> state) {
    65→    final vals = List<int>.from(state['values'] as List? ?? []);
    66→    final n = vals.length;
    67→    int si = state['stepIndex'] as int? ?? 0;
    68→    final stepsPerPass = n - 1;
    69→    final pass = si ~/ stepsPerPass;
    70→    final idx = si % stepsPerPass;
    71→    if (pass >= n - 1) {
    72→      state['comparing'] = <int>[];
    73→      state['swapped'] = <int>[];
    74→      state['sorted'] = List.generate(n, (i) => i);
    75→      return;
    76→    }
    77→    final comparing = [idx, idx + 1];
    78→    List<int> swapped = [];
    79→    if (vals[idx] > vals[idx + 1]) {
    80→      final tmp = vals[idx];
    81→      vals[idx] = vals[idx + 1];
    82→      vals[idx + 1] = tmp;
    83→      swapped = [idx, idx + 1];
    84→    }
    85→    state['values'] = vals;
    86→    state['stepIndex'] = si + 1;
    87→    state['comparing'] = comparing;
    88→    state['swapped'] = swapped;
    89→    state['sorted'] = List.generate(pass, (i) => n - 1 - i);
    90→  }
