    17→    final xMin = (scene['xMin'] as num?)?.toDouble() ?? -10.0;
    18→    final xMax = (scene['xMax'] as num?)?.toDouble() ?? 10.0;
    19→    final yMin = (scene['yMin'] as num?)?.toDouble() ?? -20.0;
    20→    final yMax = (scene['yMax'] as num?)?.toDouble() ?? 20.0;
    21→
    22→    final xRange = xMax - xMin;
    23→    final yRange = yMax - yMin;
    24→
    25→    double toCanvasX(double x) => (x - xMin) / xRange * size.width;
    26→    double toCanvasY(double y) => size.height - (y - yMin) / yRange * size.height;
    27→
    28→    // Draw axes
    29→    final axisPaint = Paint()..color = axisColor..strokeWidth = 1.0;
    30→    // X axis
    31→    final yAxisPos = toCanvasY(0).clamp(0.0, size.height);
