    33→    // Y axis
    34→    final xAxisPos = toCanvasX(0).clamp(0.0, size.width);
    35→    canvas.drawLine(Offset(xAxisPos, 0), Offset(xAxisPos, size.height), axisPaint);
    36→
    37→    // Draw axis labels
    38→    _drawAxisLabel(canvas, '0', Offset(xAxisPos + 4, yAxisPos + 4));
    39→    _drawAxisLabel(canvas, 'x', Offset(size.width - 12, yAxisPos - 14));
    40→    _drawAxisLabel(canvas, 'y', Offset(xAxisPos + 4, 4));
    41→
    42→    // Draw curve (300 points)
    43→    final curvePaint = Paint()
    44→      ..color = primaryColor
    45→      ..strokeWidth = 2.0
