     4→class IdealGasPistonRenderer extends VisualTemplateRenderer {
     5→  static const double _gasConstant = 0.08206; // L·atm/(mol·K)
     6→
     7→  const IdealGasPistonRenderer({
     8→    required super.state,
     9→    required super.scene,
    10→    required super.isDark,
    11→    super.repaint,
    12→  });
    13→
    14→  @override
    15→  void paint(Canvas canvas, Size size) {
    16→    final P = (state['P'] as num?)?.toDouble() ?? 1.0;
    17→    final n = (state['n'] as num?)?.toDouble() ?? 1.0;
    18→    final T = (state['T'] as num?)?.toDouble() ?? 273.0;
    19→
    20→    // Derived: V = nRT/P
    21→    final vDerived = (n * _gasConstant * T / P).clamp(1.0, 80.0);
    22→    final maxV = n * _gasConstant * 600 / 0.1; // max volume at extreme conditions
    23→    final minV = n * _gasConstant * 100 / 10.0;
    24→    final vFraction = ((vDerived - minV) / (maxV - minV)).clamp(0.1, 0.9);
    25→
    26→    final cylLeft = size.width * 0.25;
    27→    final cylRight = size.width * 0.75;
    28→    final cylWidth = cylRight - cylLeft;
    29→    final cylTop = size.height * 0.1;
    30→    final cylBottom = size.height * 0.85;
    31→    final cylHeight = cylBottom - cylTop;
    32→
    33→    // Cylinder walls
    34→    final wallPaint = Paint()
    35→      ..color = isDark ? const Color(0xFF30363D) : const Color(0xFFB0BEC5)
    36→      ..strokeWidth = 3.0
    37→      ..style = PaintingStyle.stroke;
    38→
    39→    // Left wall
    40→    canvas.drawLine(Offset(cylLeft, cylTop), Offset(cylLeft, cylBottom), wallPaint);
    41→    // Right wall
    42→    canvas.drawLine(Offset(cylRight, cylTop), Offset(cylRight, cylBottom), wallPaint);
    43→    // Bottom
    44→    canvas.drawLine(Offset(cylLeft, cylBottom), Offset(cylRight, cylBottom), wallPaint);
    45→
    46→    // Piston
    47→    final pistonY = cylBottom - vFraction * cylHeight;
    48→    final pistonPaint = Paint()
    49→      ..color = isDark ? const Color(0xFF484F58) : const Color(0xFF78909C)
    50→      ..style = PaintingStyle.fill;
    51→    canvas.drawRect(
    52→      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
    53→      pistonPaint,
    54→    );
    55→    canvas.drawRect(
    56→      Rect.fromLTWH(cylLeft, pistonY - 8, cylWidth, 8),
    57→      Paint()
    58→        ..color = isDark ? const Color(0xFF30363D) : const Color(0xFF90A4AE)
    59→        ..style = PaintingStyle.stroke
    60→        ..strokeWidth = 1.0,
    61→    );
    62→
    63→    // Gas region (filled)
    64→    final gasPaint = Paint()
    65→      ..color = primaryColor.withOpacity(0.15)
    66→      ..style = PaintingStyle.fill;
    67→    canvas.drawRect(
    68→      Rect.fromLTWH(cylLeft, pistonY, cylWidth, cylBottom - pistonY),
    69→      gasPaint,
    70→    );
    71→
    72→    // Labels
    73→    _drawStateLabel(canvas, P, n, T);
    74→  }
    75→
    76→  void _drawStateLabel(Canvas canvas, double P, double n, double T) {
    77→    final vDerived = n * _gasConstant * T / P;
    78→    final labels = [
    79→      'P = ${P.toStringAsFixed(1)} atm',
    80→      'V = ${vDerived.toStringAsFixed(1)} L',
    81→      'T = ${T.toStringAsFixed(0)} K',
    82→      'n = ${n.toStringAsFixed(1)} mol',
    83→    ];
    84→    double y = 8;
    85→    for (final label in labels) {
    86→      final tp = TextPainter(
    87→        text: TextSpan(
    88→          text: label,
    89→          style: TextStyle(
    90→              color: textColor, fontSize: 10, fontWeight: FontWeight.w500),
    91→        ),
    92→        textDirection: TextDirection.ltr,
    93→      )..layout();
    94→      tp.paint(canvas, Offset(8, y));
    95→      y += 14;
    96→    }
    97→  }
    98→
    99→  @override
   100→  bool shouldRepaint(IdealGasPistonRenderer old) =>
   101→      old.state['P'] != state['P'] ||
   102→      old.state['n'] != state['n'] ||
   103→      old.state['T'] != state['T'];
   104→}
