     5→class ProjectileRenderer extends VisualTemplateRenderer {
     6→  const ProjectileRenderer({
     7→    required super.state,
     8→    required super.scene,
     9→    required super.isDark,
    10→    super.repaint,
    11→  });
    12→
    13→  /// Euler integration step for projectile motion
    14→  static void simulationStep(Map<String, dynamic> state, double dt) {
    15→    final double x = (state['_x'] as num?)?.toDouble() ?? 0.0;
    16→    final double y = (state['_y'] as num?)?.toDouble() ?? 0.0;
    17→    final double vx = (state['_vx'] as num?)?.toDouble() ?? 0.0;
    18→    double vy = (state['_vy'] as num?)?.toDouble() ?? 0.0;
    19→    final double g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    20→
    21→    if (y <= 0 && (state['_launched'] as bool? ?? false) && vy < 0) {
    22→      // Hit the ground
    23→      state['_launched'] = false;
    24→      return;
    25→    }
    26→
    27→    vy -= g * dt;
    28→    final nx = x + vx * dt;
    29→    final ny = y + vy * dt;
    30→
    31→    final trail = List<Map<String, double>>.from(
    32→      (state['_trail'] as List?)
    33→              ?.map((e) => Map<String, double>.from(e as Map)) ??
    34→          [],
    35→    );
    36→    if (state['_launched'] as bool? ?? false) {
    37→      trail.add({'x': x, 'y': y});
    38→      if (trail.length > 200) trail.removeAt(0);
    39→    }
    40→
    41→    state['_x'] = nx;
    42→    state['_y'] = ny < 0 ? 0.0 : ny;
    43→    state['_vx'] = vx;
    44→    state['_vy'] = ny < 0 ? 0.0 : vy;
    45→    state['_trail'] = trail;
    46→  }
    47→
    48→  /// Launch the projectile based on angle and velocity
    49→  static void launch(Map<String, dynamic> state) {
    50→    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    51→    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    52→    final rad = angle * math.pi / 180;
    53→    state['_x'] = 0.0;
    54→    state['_y'] = 0.0;
    55→    state['_vx'] = v0 * math.cos(rad);
    56→    state['_vy'] = v0 * math.sin(rad);
    57→    state['_trail'] = <Map<String, double>>[];
    58→    state['_launched'] = true;
    59→  }
    60→
    61→  @override
    62→  void paint(Canvas canvas, Size size) {
    63→    final angle = (state['angle'] as num?)?.toDouble() ?? 45.0;
    64→    final v0 = (state['velocity'] as num?)?.toDouble() ?? 20.0;
    65→    final g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    66→    final launched = state['_launched'] as bool? ?? false;
    67→
    68→    // Calculate trajectory range for scaling
    69→    final rad = angle * math.pi / 180;
    70→    final totalTime = 2 * v0 * math.sin(rad) / g;
    71→    final maxRange = v0 * math.cos(rad) * totalTime;
    72→    final maxHeight = math.pow(v0 * math.sin(rad), 2) / (2 * g);
    73→    final scaleX = maxRange > 0 ? (size.width * 0.9) / maxRange : 1.0;
    74→    final scaleY = maxHeight > 0 ? (size.height * 0.8) / maxHeight : 1.0;
    75→
    76→    double toCanvasX(double wx) => size.width * 0.05 + wx * scaleX;
    77→    double toCanvasY(double wy) => size.height * 0.9 - wy * scaleY;
    78→
    79→    // Draw ground
    80→    canvas.drawLine(
    81→      Offset(0, toCanvasY(0)),
    82→      Offset(size.width, toCanvasY(0)),
    83→      Paint()
    84→        ..color = axisColor
    85→        ..strokeWidth = 1.5,
    86→    );
    87→
    88→    // Draw predicted trajectory (dashed)
    89→    if (!launched) {
    90→      final dashPaint = Paint()
    91→        ..color = axisColor.withOpacity(0.5)
    92→        ..strokeWidth = 1.0
    93→        ..style = PaintingStyle.stroke;
    94→      final path = Path();
    95→      bool first = true;
    96→      for (int i = 0; i <= 100; i++) {
    97→        final t = (i / 100) * totalTime;
    98→        final wx = v0 * math.cos(rad) * t;
    99→        final wy = v0 * math.sin(rad) * t - 0.5 * g * t * t;
   100→        if (wy < 0) break;
   101→        final cx = toCanvasX(wx);
   102→        final cy = toCanvasY(wy);
   103→        if (first) {
   104→          path.moveTo(cx, cy);
   105→          first = false;
   106→        } else {
   107→          path.lineTo(cx, cy);
   108→        }
   109→      }
   110→      canvas.drawPath(path, dashPaint);
   111→    }
   112→
   113→    // Draw trail
   114→    final trail = (state['_trail'] as List?)
   115→            ?.map((e) => Map<String, double>.from(e as Map))
   116→            .toList() ??
   117→        [];
   118→    if (trail.length > 1) {
   119→      final trailPaint = Paint()
   120→        ..color = primaryColor.withOpacity(0.5)
   121→        ..strokeWidth = 2.0
   122→        ..style = PaintingStyle.stroke;
   123→      final path = Path();
   124→      path.moveTo(toCanvasX(trail.first['x']!), toCanvasY(trail.first['y']!));
   125→      for (final pt in trail.skip(1)) {
   126→        path.lineTo(toCanvasX(pt['x']!), toCanvasY(pt['y']!));
   127→      }
   128→      canvas.drawPath(path, trailPaint);
   129→    }
   130→
   131→    // Draw current ball
   132→    final curX = (state['_x'] as num?)?.toDouble() ?? 0.0;
   133→    final curY = (state['_y'] as num?)?.toDouble() ?? 0.0;
   134→    canvas.drawCircle(
   135→      Offset(toCanvasX(curX), toCanvasY(curY)),
   136→      6,
   137→      Paint()..color = accentColor,
   138→    );
   139→
   140→    // Info label
   141→    final infoText = launched
   142→        ? 'x=${curX.toStringAsFixed(1)}m  y=${curY.toStringAsFixed(1)}m'
   143→        : '${angle.toStringAsFixed(0)}° @ ${v0.toStringAsFixed(0)} m/s';
   144→    final tp = TextPainter(
   145→      text:
   146→          TextSpan(text: infoText, style: TextStyle(color: labelColor, fontSize: 10)),
   147→      textDirection: TextDirection.ltr,
   148→    )..layout();
   149→    tp.paint(canvas, const Offset(8, 8));
   150→  }
   151→
   152→  @override
   153→  bool shouldRepaint(ProjectileRenderer old) =>
   154→      old.state['_x'] != state['_x'] ||
   155→      old.state['_y'] != state['_y'] ||
   156→      old.state['angle'] != state['angle'] ||
   157→      old.state['velocity'] != state['velocity'] ||
   158→      old.state['_launched'] != state['_launched'];
   159→}
