import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class PendulumRenderer extends VisualTemplateRenderer {
  const PendulumRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  static void launch(Map<String, dynamic> state) {
    state['angle'] = (state['angle0'] as num?)?.toDouble() ?? 30.0;
    state['_omega'] = 0.0;
  }

  static void simulationStep(Map<String, dynamic> state, double dt) {
    if (!state.containsKey('angle')) {
      state['angle'] = (state['angle0'] as num?)?.toDouble() ?? 30.0;
      state['_omega'] = 0.0;
    }
    final double g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    final double l = (state['length'] as num?)?.toDouble() ?? 1.5;
    final double angle = (state['angle'] as num?)?.toDouble() ?? 30.0;
    double omega = (state['_omega'] as num?)?.toDouble() ?? 0.0;
    final double angleRad = angle * math.pi / 180.0;
    omega += -(g / l) * math.sin(angleRad) * dt;
    omega *= 0.9995; // damping
    state['_omega'] = omega;
    state['angle'] = angle + omega * (180.0 / math.pi) * dt;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double angleDeg = (state['angle'] as num?)?.toDouble() ??
        (state['angle0'] as num?)?.toDouble() ??
        30.0;
    final double l = (state['length'] as num?)?.toDouble() ?? 1.5;
    final double g = (state['gravity'] as num?)?.toDouble() ?? 9.8;
    final double angleRad = angleDeg * math.pi / 180.0;

    final double pivotX = size.width / 2;
    final double pivotY = size.height * 0.15;

    // Scale rope length to canvas
    final double scale = math.min(size.width, size.height) * 0.55 / 2.0;
    final double ropeLen = l * scale;

    final double bobX = pivotX + ropeLen * math.sin(angleRad);
    final double bobY = pivotY + ropeLen * math.cos(angleRad);

    // Dashed equilibrium line
    final dashPaint = Paint()
      ..color = axisColor.withOpacity(0.4)
      ..strokeWidth = 1.0
      ..style = PaintingStyle.stroke;
    _drawDashedLine(
      canvas,
      Offset(pivotX, pivotY),
      Offset(pivotX, pivotY + ropeLen + 16),
      dashPaint,
    );

    // Angle arc
    if (angleDeg.abs() > 1.0) {
      final arcPaint = Paint()
        ..color = accentColor.withOpacity(0.6)
        ..strokeWidth = 1.5
        ..style = PaintingStyle.stroke;
      final arcRect = Rect.fromCircle(
        center: Offset(pivotX, pivotY),
        radius: ropeLen * 0.3,
      );
      final startAngle = -math.pi / 2;
      final sweepAngle = angleRad;
      canvas.drawArc(arcRect, startAngle, sweepAngle, false, arcPaint);
    }

    // Rope (string)
    canvas.drawLine(
      Offset(pivotX, pivotY),
      Offset(bobX, bobY),
      Paint()
        ..color = axisColor
        ..strokeWidth = 1.5,
    );

    // Pivot
    canvas.drawCircle(
      Offset(pivotX, pivotY),
      5,
      Paint()..color = axisColor,
    );

    // Bob
    canvas.drawCircle(
      Offset(bobX, bobY),
      14,
      Paint()..color = primaryColor,
    );
    canvas.drawCircle(
      Offset(bobX, bobY),
      14,
      Paint()
        ..color = primaryColor.withOpacity(0.4)
        ..strokeWidth = 2
        ..style = PaintingStyle.stroke,
    );

    // Labels
    final period = 2 * math.pi * math.sqrt(l / g);
    _drawLabel(canvas, '${angleDeg.toStringAsFixed(1)}°', Offset(8, 8));
    _drawLabel(canvas, 'T = ${period.toStringAsFixed(2)} s', Offset(8, 22));
    _drawLabel(
        canvas, 'L = ${l.toStringAsFixed(1)} m', Offset(8, 36));
  }

  void _drawDashedLine(
      Canvas canvas, Offset start, Offset end, Paint paint) {
    const dashLen = 5.0;
    const gapLen = 4.0;
    final dir = end - start;
    final total = dir.distance;
    final unit = dir / total;
    double pos = 0;
    while (pos < total) {
      final from = start + unit * pos;
      final to = start + unit * math.min(pos + dashLen, total);
      canvas.drawLine(from, to, paint);
      pos += dashLen + gapLen;
    }
  }

  void _drawLabel(Canvas canvas, String text, Offset offset) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: labelColor, fontSize: 10),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(PendulumRenderer old) =>
      old.state['angle'] != state['angle'] ||
      old.state['length'] != state['length'] ||
      old.state['gravity'] != state['gravity'] ||
      old.state['angle0'] != state['angle0'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class WaveRenderer extends VisualTemplateRenderer {
  const WaveRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  static void simulationStep(Map<String, dynamic> state, double dt) {
    state['_time'] = ((state['_time'] as num?)?.toDouble() ?? 0.0) + dt;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double A = (state['amplitude'] as num?)?.toDouble() ?? 0.5;
    final double f = (state['frequency'] as num?)?.toDouble() ?? 1.0;
    final double speed = (state['speed'] as num?)?.toDouble() ?? 1.0;
    final double t = (state['_time'] as num?)?.toDouble() ?? 0.0;
    final double lambda = f > 0 ? speed / f : 1.0;

    final double centerY = size.height / 2;
    // amplitude in pixels — uses 40% of half-height
    final double ampPx = A * size.height * 0.4;

    // X axis
    canvas.drawLine(
      Offset(0, centerY),
      Offset(size.width, centerY),
      Paint()
        ..color = axisColor
        ..strokeWidth = 1.0,
    );

    // Wave path
    final wavePaint = Paint()
      ..color = primaryColor
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round;

    final path = Path();
    const int samples = 300;
    for (int i = 0; i <= samples; i++) {
      final double xFrac = i / samples;
      final double xPx = xFrac * size.width;
      // y(x,t) = A * sin(2π*f*x/visWidth - 2π*f*t)
      final double phase = 2 * math.pi * f * xFrac - 2 * math.pi * f * t;
      final double yPx = centerY - ampPx * math.sin(phase);
      if (i == 0) {
        path.moveTo(xPx, yPx);
      } else {
        path.lineTo(xPx, yPx);
      }
    }
    canvas.drawPath(path, wavePaint);

    // Amplitude annotation (peak)
    final double peakX = size.width * 0.15;
    final double peakY = centerY - ampPx;
    canvas.drawLine(
      Offset(peakX + 20, centerY),
      Offset(peakX + 20, peakY),
      Paint()
        ..color = accentColor.withOpacity(0.7)
        ..strokeWidth = 1.5
        ..style = PaintingStyle.stroke,
    );
    _drawLabel(canvas, 'A', Offset(peakX + 22, (centerY + peakY) / 2 - 6),
        accentColor);

    // Labels
    _drawLabel(canvas, 'A = ${A.toStringAsFixed(2)}', Offset(8, 8), labelColor);
    _drawLabel(
        canvas, 'f = ${f.toStringAsFixed(2)} Hz', Offset(8, 22), labelColor);
    _drawLabel(
        canvas,
        'λ = ${lambda.toStringAsFixed(2)} m',
        Offset(8, 36),
        labelColor);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: color, fontSize: 10),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(WaveRenderer old) =>
      old.state['_time'] != state['_time'] ||
      old.state['amplitude'] != state['amplitude'] ||
      old.state['frequency'] != state['frequency'] ||
      old.state['speed'] != state['speed'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class PythagoreanRenderer extends VisualTemplateRenderer {
  const PythagoreanRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double a = (state['a'] as num?)?.toDouble() ?? 3.0;
    final double b = (state['b'] as num?)?.toDouble() ?? 4.0;
    final double c = math.sqrt(a * a + b * b);

    // Scale so that the whole diagram fits (triangle + squares).
    // We need space: horizontally b + c, vertically a + c (rough)
    final double maxDim = math.max(a + c, b + c);
    final double scale = math.min(size.width, size.height) * 0.4 / maxDim;

    // Triangle origin (bottom-left vertex) – shifted right/up to leave room for squares
    final double originX = size.width * 0.28;
    final double originY = size.height * 0.78;

    final double aPx = a * scale; // vertical leg (up)
    final double bPx = b * scale; // horizontal leg (right)
    final double cPx = c * scale; // hypotenuse

    // Triangle vertices
    final Offset vA = Offset(originX, originY); // bottom-left
    final Offset vB = Offset(originX + bPx, originY); // bottom-right
    final Offset vC = Offset(originX, originY - aPx); // top-left

    // Draw triangle fill
    final triPath = Path()
      ..moveTo(vA.dx, vA.dy)
      ..lineTo(vB.dx, vB.dy)
      ..lineTo(vC.dx, vC.dy)
      ..close();
    canvas.drawPath(
      triPath,
      Paint()
        ..color = textColor.withOpacity(0.08)
        ..style = PaintingStyle.fill,
    );
    canvas.drawPath(
      triPath,
      Paint()
        ..color = axisColor
        ..strokeWidth = 2.0
        ..style = PaintingStyle.stroke,
    );

    // Right angle mark
    const double rm = 8.0;
    canvas.drawPath(
      Path()
        ..moveTo(vA.dx + rm, vA.dy)
        ..lineTo(vA.dx + rm, vA.dy - rm)
        ..lineTo(vA.dx, vA.dy - rm),
      Paint()
        ..color = axisColor
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke,
    );

    // Square on side a (left of triangle)
    _drawSquare(
      canvas,
      vA,
      Offset(vA.dx - aPx, vA.dy),
      Offset(vA.dx - aPx, vA.dy - aPx),
      vC,
      primaryColor,
      'a²=${(a * a).toStringAsFixed(1)}',
    );

    // Square on side b (below triangle)
    _drawSquare(
      canvas,
      vB,
      Offset(vB.dx, vB.dy + bPx),
      Offset(vA.dx, vA.dy + bPx),
      vA,
      successColor,
      'b²=${(b * b).toStringAsFixed(1)}',
    );

    // Square on hypotenuse c (upper-right)
    // Direction perpendicular to hypotenuse (outward)
    final double hx = (vB.dx - vC.dx) / cPx;
    final double hy = (vB.dy - vC.dy) / cPx;
    // Perpendicular (outward from triangle)
    final double px = -hy;
    final double py = hx;
    final Offset vD = Offset(vC.dx + px * cPx, vC.dy + py * cPx);
    final Offset vE = Offset(vB.dx + px * cPx, vB.dy + py * cPx);
    _drawSquare(canvas, vC, vD, vE, vB, accentColor,
        'c²=${(c * c).toStringAsFixed(1)}');

    // Side labels on triangle edges
    _drawLabel(
      canvas,
      'a=${a.toStringAsFixed(1)}',
      Offset(vC.dx - 36, (vA.dy + vC.dy) / 2),
      textColor,
    );
    _drawLabel(
      canvas,
      'b=${b.toStringAsFixed(1)}',
      Offset((vA.dx + vB.dx) / 2 - 12, vA.dy + 8),
      textColor,
    );
    _drawLabel(
      canvas,
      'c=${c.toStringAsFixed(2)}',
      Offset((vC.dx + vB.dx) / 2 + 4, (vC.dy + vB.dy) / 2 - 6),
      textColor,
    );

    // Equation at top
    final eqText =
        'a²+b²=c²:  ${(a * a).toStringAsFixed(1)}+${(b * b).toStringAsFixed(1)}=${(c * c).toStringAsFixed(1)}';
    _drawLabel(canvas, eqText, Offset(8, 8), labelColor);
  }

  void _drawSquare(Canvas canvas, Offset p1, Offset p2, Offset p3, Offset p4,
      Color color, String label) {
    final path = Path()
      ..moveTo(p1.dx, p1.dy)
      ..lineTo(p2.dx, p2.dy)
      ..lineTo(p3.dx, p3.dy)
      ..lineTo(p4.dx, p4.dy)
      ..close();
    canvas.drawPath(path, Paint()..color = color.withOpacity(0.25));
    canvas.drawPath(
      path,
      Paint()
        ..color = color
        ..strokeWidth = 1.5
        ..style = PaintingStyle.stroke,
    );
    // Label at center
    final cx = (p1.dx + p2.dx + p3.dx + p4.dx) / 4;
    final cy = (p1.dy + p2.dy + p3.dy + p4.dy) / 4;
    _drawLabel(canvas, label, Offset(cx - 18, cy - 6), color);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(color: color, fontSize: 9),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(PythagoreanRenderer old) =>
      old.state['a'] != state['a'] || old.state['b'] != state['b'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class SpringMassRenderer extends VisualTemplateRenderer {
  const SpringMassRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  static void launch(Map<String, dynamic> state) {
    state['_disp'] = (state['displacement'] as num?)?.toDouble() ?? 0.5;
    state['_velocity'] = 0.0;
  }

  static void simulationStep(Map<String, dynamic> state, double dt) {
    if (!state.containsKey('_disp')) return;
    final double k = (state['spring_k'] as num?)?.toDouble() ?? 10.0;
    final double m = (state['mass'] as num?)?.toDouble() ?? 1.0;
    double disp = (state['_disp'] as num?)?.toDouble() ?? 0.0;
    double vel = (state['_velocity'] as num?)?.toDouble() ?? 0.0;
    final double acc = -(k / m) * disp;
    vel += acc * dt;
    vel *= 0.999; // damping
    disp += vel * dt;
    state['_disp'] = disp;
    state['_velocity'] = vel;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final double k = (state['spring_k'] as num?)?.toDouble() ?? 10.0;
    final double m = (state['mass'] as num?)?.toDouble() ?? 1.0;
    final double disp = (state['_disp'] as num?)?.toDouble() ??
        (state['displacement'] as num?)?.toDouble() ??
        0.5;

    final double centerY = size.height * 0.45;
    final double wallX = size.width * 0.05;
    final double massWidth = 40.0;
    final double massHeight = 40.0;

    // Equilibrium position of mass left edge
    final double eqX = size.width * 0.55;
    // Current position based on displacement (scaled to canvas)
    final double dispScale = size.width * 0.15;
    final double massX = eqX + disp * dispScale;

    // Wall (hatching)
    _drawWall(canvas, wallX, centerY - massHeight / 2 - 8,
        centerY + massHeight / 2 + 8);

    // Equilibrium dashed line
    _drawDashedLine(
      canvas,
      Offset(eqX + massWidth / 2, centerY - massHeight / 2 - 14),
      Offset(eqX + massWidth / 2, centerY + massHeight / 2 + 14),
      Paint()
        ..color = axisColor.withOpacity(0.4)
        ..strokeWidth = 1.0,
    );

    // Spring (zigzag)
    _drawSpring(
      canvas,
      Offset(wallX, centerY),
      Offset(massX, centerY),
    );

    // Mass block
    final massRect = Rect.fromLTWH(
      massX,
      centerY - massHeight / 2,
      massWidth,
      massHeight,
    );
    canvas.drawRect(massRect, Paint()..color = primaryColor);
    canvas.drawRect(
      massRect,
      Paint()
        ..color = primaryColor.withOpacity(0.6)
        ..strokeWidth = 2
        ..style = PaintingStyle.stroke,
    );

    // Mass label
    _drawLabelCentered(
      canvas,
      'm=${m.toStringAsFixed(1)} kg',
      Offset(massX + massWidth / 2, centerY),
    );

    // Force arrow if displaced
    if (disp.abs() > 0.02) {
      final double arrowStart = massX + (disp > 0 ? massWidth : 0);
      final double arrowEnd = eqX + (disp > 0 ? massWidth / 2 : massWidth / 2);
      _drawArrow(canvas, Offset(arrowStart, centerY - massHeight / 2 - 14),
          Offset(arrowEnd, centerY - massHeight / 2 - 14), errorColor);
      _drawLabel(
        canvas,
        'F=-kx',
        Offset(
            math.min(arrowStart, arrowEnd),
            centerY - massHeight / 2 - 26),
        errorColor,
      );
    }

    // Labels
    final double period = 2 * math.pi * math.sqrt(m / k);
    _drawLabel(canvas, 'k = ${k.toStringAsFixed(1)} N/m', Offset(8, 8),
        labelColor);
    _drawLabel(canvas, 'm = ${m.toStringAsFixed(1)} kg', Offset(8, 22),
        labelColor);
    _drawLabel(
        canvas,
        'x = ${disp.toStringAsFixed(3)} m',
        Offset(8, 36),
        labelColor);
    _drawLabel(
        canvas,
        'T = ${period.toStringAsFixed(2)} s',
        Offset(8, 50),
        labelColor);
  }

  void _drawWall(Canvas canvas, double x, double top, double bottom) {
    canvas.drawLine(
      Offset(x, top),
      Offset(x, bottom),
      Paint()
        ..color = axisColor
        ..strokeWidth = 3.0,
    );
    const double hatchStep = 8.0;
    final hatchPaint = Paint()
      ..color = axisColor.withOpacity(0.5)
      ..strokeWidth = 1.0;
    double y = top;
    while (y < bottom) {
      canvas.drawLine(Offset(x, y), Offset(x - 8, y + 8), hatchPaint);
      y += hatchStep;
    }
  }

  void _drawSpring(Canvas canvas, Offset start, Offset end) {
    final double length = (end - start).distance;
    const int coils = 10;
    const double amplitude = 8.0;
    final double segLen = length / (coils * 2 + 2);
    final paint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;

    final path = Path()..moveTo(start.dx, start.dy);
    // Lead segment
    path.lineTo(start.dx + segLen, start.dy);
    for (int i = 0; i < coils; i++) {
      final double x0 = start.dx + segLen + i * 2 * segLen;
      path.lineTo(x0 + segLen, start.dy - amplitude);
      path.lineTo(x0 + 2 * segLen, start.dy + amplitude);
    }
    // Trail segment
    path.lineTo(end.dx, end.dy);
    canvas.drawPath(path, paint);
  }

  void _drawDashedLine(
      Canvas canvas, Offset start, Offset end, Paint paint) {
    const dashLen = 5.0;
    const gapLen = 4.0;
    final dir = end - start;
    final total = dir.distance;
    if (total == 0) return;
    final unit = dir / total;
    double pos = 0;
    while (pos < total) {
      final from = start + unit * pos;
      final to = start + unit * math.min(pos + dashLen, total);
      canvas.drawLine(from, to, paint);
      pos += dashLen + gapLen;
    }
  }

  void _drawArrow(Canvas canvas, Offset from, Offset to, Color color) {
    final paint = Paint()
      ..color = color
      ..strokeWidth = 2.0;
    canvas.drawLine(from, to, paint);
    // Arrowhead
    final dir = to - from;
    final len = dir.distance;
    if (len < 4) return;
    final unit = dir / len;
    final perp = Offset(-unit.dy, unit.dx);
    canvas.drawLine(to, to - unit * 8 + perp * 4, paint);
    canvas.drawLine(to, to - unit * 8 - perp * 4, paint);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(text: text, style: TextStyle(color: color, fontSize: 10)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  void _drawLabelCentered(Canvas canvas, String text, Offset center) {
    final tp = TextPainter(
      text: TextSpan(
          text: text,
          style: TextStyle(
              color: Colors.white, fontSize: 9, fontWeight: FontWeight.w600)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width / 2, center.dy - tp.height / 2));
  }

  @override
  bool shouldRepaint(SpringMassRenderer old) =>
      old.state['_disp'] != state['_disp'] ||
      old.state['spring_k'] != state['spring_k'] ||
      old.state['mass'] != state['mass'] ||
      old.state['displacement'] != state['displacement'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class OhmsLawRenderer extends VisualTemplateRenderer {
  const OhmsLawRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double v = (state['voltage'] as num?)?.toDouble() ?? 5.0;
    final double r = ((state['resistance'] as num?)?.toDouble() ?? 100.0)
        .clamp(0.1, 10000.0);
    final double i = (v / r).clamp(0.0, 100.0);

    // Circuit layout
    final double left = size.width * 0.12;
    final double right = size.width * 0.65;
    final double top = size.height * 0.12;
    final double bottom = size.height * 0.65;
    final double midH = (top + bottom) / 2;

    final wirePaint = Paint()
      ..color = axisColor
      ..strokeWidth = 2.0;

    // Draw circuit box
    // Top wire: left → right
    canvas.drawLine(Offset(left, top), Offset(right, top), wirePaint);
    // Right wire: top → bottom
    canvas.drawLine(Offset(right, top), Offset(right, bottom), wirePaint);
    // Bottom wire: right → left
    canvas.drawLine(Offset(right, bottom), Offset(left, bottom), wirePaint);
    // Left wire: bottom → top (with battery gap)
    canvas.drawLine(
        Offset(left, bottom), Offset(left, midH + 20), wirePaint);
    canvas.drawLine(
        Offset(left, midH - 20), Offset(left, top), wirePaint);

    // Battery on left side
    _drawBattery(canvas, Offset(left, midH), v);

    // Resistor on top wire (centered)
    final double rMidX = (left + right) / 2;
    _drawResistor(canvas, Offset(rMidX, top));

    // Current arrows
    _drawCurrentArrow(canvas, Offset((left + right) * 0.75, top - 10),
        Offset((left + right) * 0.85, top - 10), accentColor);
    _drawCurrentArrow(canvas, Offset(right + 10, (top + bottom) * 0.6),
        Offset(right + 10, (top + bottom) * 0.7), accentColor);
    _drawCurrentArrow(canvas, Offset((left + right) * 0.4, bottom + 10),
        Offset((left + right) * 0.3, bottom + 10), accentColor);

    // Value labels
    final double labelX = size.width * 0.70;
    _drawValueBox(canvas, 'V', '${v.toStringAsFixed(1)} V', primaryColor,
        Offset(labelX, size.height * 0.12));
    _drawValueBox(canvas, 'I', '${(i * 1000).toStringAsFixed(1)} mA',
        accentColor, Offset(labelX, size.height * 0.32));
    _drawValueBox(canvas, 'R', '${r.toStringAsFixed(0)} Ω', successColor,
        Offset(labelX, size.height * 0.52));

    // Equation
    _drawLabel(canvas, 'V = IR', Offset(8, 8), textColor, bold: true);
    _drawLabel(
        canvas,
        '${v.toStringAsFixed(1)} = ${(i * 1000).toStringAsFixed(1)}mA × ${r.toStringAsFixed(0)}Ω',
        Offset(8, 22),
        labelColor);

    // Bar chart at bottom
    _drawBarChart(canvas, size, v, i, r);
  }

  void _drawBattery(Canvas canvas, Offset center, double voltage) {
    final Paint p = Paint()
      ..color = primaryColor
      ..strokeWidth = 2.0;
    // Long line (positive)
    canvas.drawLine(
        Offset(center.dx - 14, center.dy - 6),
        Offset(center.dx + 14, center.dy - 6),
        p..strokeWidth = 3.0);
    // Short line (negative)
    canvas.drawLine(
        Offset(center.dx - 8, center.dy + 6),
        Offset(center.dx + 8, center.dy + 6),
        p..strokeWidth = 1.5);
    // V label
    _drawLabel(canvas, '${voltage.toStringAsFixed(1)}V',
        Offset(center.dx + 16, center.dy - 8), primaryColor);
  }

  void _drawResistor(Canvas canvas, Offset center) {
    const double w = 40.0;
    const double h = 12.0;
    final Paint p = Paint()
      ..color = successColor
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke;
    // Zigzag resistor symbol
    final path = Path()
      ..moveTo(center.dx - w / 2, center.dy);
    const int peaks = 6;
    final double segW = w / peaks;
    for (int i = 0; i < peaks; i++) {
      final double x = center.dx - w / 2 + i * segW;
      path.lineTo(x + segW / 2, center.dy - (i.isEven ? h : -h));
      path.lineTo(x + segW, center.dy);
    }
    canvas.drawPath(path, p);
    _drawLabel(canvas, 'R', Offset(center.dx - 4, center.dy - h - 16),
        successColor);
  }

  void _drawCurrentArrow(
      Canvas canvas, Offset from, Offset to, Color color) {
    final paint = Paint()
      ..color = color.withOpacity(0.8)
      ..strokeWidth = 1.5;
    canvas.drawLine(from, to, paint);
    final dir = to - from;
    final len = dir.distance;
    if (len < 4) return;
    final unit = dir / len;
    final perp = Offset(-unit.dy, unit.dx);
    canvas.drawLine(to, to - unit * 6 + perp * 3, paint);
    canvas.drawLine(to, to - unit * 6 - perp * 3, paint);
  }

  void _drawValueBox(
      Canvas canvas, String key, String value, Color color, Offset pos) {
    final boxRect = Rect.fromLTWH(pos.dx, pos.dy, 80, 28);
    canvas.drawRRect(
      RRect.fromRectAndRadius(boxRect, const Radius.circular(4)),
      Paint()..color = color.withOpacity(0.15),
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(boxRect, const Radius.circular(4)),
      Paint()
        ..color = color
        ..strokeWidth = 1.0
        ..style = PaintingStyle.stroke,
    );
    _drawLabel(canvas, key, Offset(pos.dx + 6, pos.dy + 7), color);
    _drawLabel(canvas, value, Offset(pos.dx + 20, pos.dy + 7), color);
  }

  void _drawBarChart(
      Canvas canvas, Size size, double v, double i, double r) {
    final double chartLeft = size.width * 0.10;
    final double chartBottom = size.height * 0.95;
    final double chartHeight = size.height * 0.2;
    final double barW = size.width * 0.08;

    // Normalize bars for display
    final double vNorm = (v / 12.0).clamp(0.0, 1.0);
    final double iNorm = (i * 50).clamp(0.0, 1.0); // i in A, *50
    final double rNorm = (r / 1000.0).clamp(0.0, 1.0);

    final List<(double, Color, String)> bars = [
      (vNorm, primaryColor, 'V'),
      (iNorm, accentColor, 'I'),
      (rNorm, successColor, 'R'),
    ];

    for (int idx = 0; idx < bars.length; idx++) {
      final (norm, color, label) = bars[idx];
      final double x = chartLeft + idx * (barW + 8);
      final double barH = norm * chartHeight;
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromLTWH(x, chartBottom - barH, barW, barH),
          const Radius.circular(3),
        ),
        Paint()..color = color.withOpacity(0.8),
      );
      _drawLabel(canvas, label, Offset(x + barW / 2 - 4, chartBottom + 2),
          labelColor);
    }
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color,
      {bool bold = false}) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: color,
          fontSize: 10,
          fontWeight: bold ? FontWeight.w700 : FontWeight.normal,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(OhmsLawRenderer old) =>
      old.state['voltage'] != state['voltage'] ||
      old.state['resistance'] != state['resistance'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class DerivativeRenderer extends VisualTemplateRenderer {
  const DerivativeRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double xVal = (state['x'] as num?)?.toDouble() ?? 1.0;
    final double a = (state['a'] as num?)?.toDouble() ?? 1.0;
    final double b = (state['b'] as num?)?.toDouble() ?? 0.0;
    final double c = (state['c'] as num?)?.toDouble() ?? -2.0;

    // f(x) = ax² + bx + c
    double f(double x) => a * x * x + b * x + c;
    // f'(x) = 2ax + b
    double df(double x) => 2 * a * x + b;

    const double xMin = -5.0;
    const double xMax = 5.0;

    // Compute y range from parabola
    final double yAtBound1 = f(xMin);
    final double yAtBound2 = f(xMax);
    double yMin = math.min(yAtBound1, yAtBound2);
    double yMax = math.max(yAtBound1, yAtBound2);
    if (a.abs() > 0.001) {
      final double vx = -b / (2 * a);
      final double vy = f(vx);
      yMin = math.min(yMin, vy);
      yMax = math.max(yMax, vy);
    }
    // Expand y range for tangent line
    final double slope = df(xVal);
    final double ty1 = f(xVal) + slope * (xMin - xVal);
    final double ty2 = f(xVal) + slope * (xMax - xVal);
    yMin = math.min(yMin, math.min(ty1, ty2)) - 2;
    yMax = math.max(yMax, math.max(ty1, ty2)) + 2;
    // Guard against degenerate range
    if ((yMax - yMin).abs() < 1) {
      yMax = yMin + 10;
    }

    final double xRange = xMax - xMin;
    final double yRange = yMax - yMin;

    double toCanvasX(double x) =>
        (x - xMin) / xRange * size.width;
    double toCanvasY(double y) =>
        size.height - (y - yMin) / yRange * size.height;

    // Axes
    final axisPaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.0;
    final double yAxisPx = toCanvasY(0).clamp(0.0, size.height);
    final double xAxisPx = toCanvasX(0).clamp(0.0, size.width);
    canvas.drawLine(Offset(0, yAxisPx), Offset(size.width, yAxisPx), axisPaint);
    canvas.drawLine(
        Offset(xAxisPx, 0), Offset(xAxisPx, size.height), axisPaint);

    // Parabola
    final curvePaint = Paint()
      ..color = primaryColor
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke;
    final path = Path();
    bool first = true;
    for (int i = 0; i <= 300; i++) {
      final double x = xMin + (i / 300) * xRange;
      final double y = f(x);
      final double cx = toCanvasX(x);
      final double cy = toCanvasY(y);
      if (cy.isNaN || cy.isInfinite || cy < -10 || cy > size.height + 10) {
        first = true;
        continue;
      }
      if (first) {
        path.moveTo(cx, cy);
        first = false;
      } else {
        path.lineTo(cx, cy);
      }
    }
    canvas.drawPath(path, curvePaint);

    // Tangent line (extend ±3 units from xVal)
    const double ext = 3.0;
    final double txLeft = xVal - ext;
    final double txRight = xVal + ext;
    final double tyLeft = f(xVal) + slope * (-ext);
    final double tyRight = f(xVal) + slope * ext;
    final tangentPaint = Paint()
      ..color = accentColor
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    canvas.drawLine(
      Offset(toCanvasX(txLeft), toCanvasY(tyLeft)),
      Offset(toCanvasX(txRight), toCanvasY(tyRight)),
      tangentPaint,
    );

    // Slope triangle (rise/run dashed)
    final double runEnd = xVal + 1.0;
    final double riseEnd = f(xVal) + slope;
    final dashPaint = Paint()
      ..color = accentColor.withOpacity(0.5)
      ..strokeWidth = 1.0
      ..style = PaintingStyle.stroke;
    _drawDashedLine(
      canvas,
      Offset(toCanvasX(xVal), toCanvasY(f(xVal))),
      Offset(toCanvasX(runEnd), toCanvasY(f(xVal))),
      dashPaint,
    );
    _drawDashedLine(
      canvas,
      Offset(toCanvasX(runEnd), toCanvasY(f(xVal))),
      Offset(toCanvasX(runEnd), toCanvasY(riseEnd)),
      dashPaint,
    );

    // Point P
    canvas.drawCircle(
      Offset(toCanvasX(xVal), toCanvasY(f(xVal))),
      5,
      Paint()..color = accentColor,
    );

    // Labels at bottom
    final double fx = f(xVal);
    final double dfx = df(xVal);
    _drawLabel(
        canvas, 'f(x) = ${a.toStringAsFixed(1)}x²+${b.toStringAsFixed(1)}x+${c.toStringAsFixed(1)}',
        Offset(8, size.height - 38), labelColor);
    _drawLabel(
        canvas,
        "f'(x) = ${dfx.toStringAsFixed(2)}  at x=${xVal.toStringAsFixed(1)}",
        Offset(8, size.height - 24),
        accentColor);
    _drawLabel(
        canvas,
        'f(${xVal.toStringAsFixed(1)}) = ${fx.toStringAsFixed(2)}',
        Offset(8, size.height - 10),
        primaryColor);
  }

  void _drawDashedLine(
      Canvas canvas, Offset start, Offset end, Paint paint) {
    const dashLen = 5.0;
    const gapLen = 4.0;
    final dir = end - start;
    final total = dir.distance;
    if (total == 0) return;
    final unit = dir / total;
    double pos = 0;
    while (pos < total) {
      final from = start + unit * pos;
      final to = start + unit * math.min(pos + dashLen, total);
      canvas.drawLine(from, to, paint);
      pos += dashLen + gapLen;
    }
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color) {
    final tp = TextPainter(
      text: TextSpan(
          text: text, style: TextStyle(color: color, fontSize: 10)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(DerivativeRenderer old) =>
      old.state['x'] != state['x'] ||
      old.state['a'] != state['a'] ||
      old.state['b'] != state['b'] ||
      old.state['c'] != state['c'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class BohrModelRenderer extends VisualTemplateRenderer {
  const BohrModelRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  static void simulationStep(Map<String, dynamic> state, double dt) {
    state['_time'] = ((state['_time'] as num?)?.toDouble() ?? 0.0) + dt;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final int protons = (state['protons'] as num?)?.toInt() ?? 6;
    final int neutrons = (state['neutrons'] as num?)?.toInt() ?? 6;
    final int shell1 = (state['shell1'] as num?)?.toInt() ?? 2;
    final int shell2 = (state['shell2'] as num?)?.toInt() ?? 4;
    final int shell3 = (state['shell3'] as num?)?.toInt() ?? 0;
    final double t = (state['_time'] as num?)?.toDouble() ?? 0.0;

    final double cx = size.width / 2;
    final double cy = size.height * 0.48;
    final double minDim = math.min(size.width, size.height);

    // Shell radii (scaled)
    final double r1 = minDim * 0.18;
    final double r2 = minDim * 0.30;
    final double r3 = minDim * 0.42;

    final orbitPaint = Paint()
      ..color = axisColor.withOpacity(0.4)
      ..strokeWidth = 1.0
      ..style = PaintingStyle.stroke;

    // Draw shells
    if (shell1 > 0) canvas.drawCircle(Offset(cx, cy), r1, orbitPaint);
    if (shell2 > 0) canvas.drawCircle(Offset(cx, cy), r2, orbitPaint);
    if (shell3 > 0) canvas.drawCircle(Offset(cx, cy), r3, orbitPaint);

    // Nucleus
    final double nucleusR = (minDim * 0.07).clamp(10.0, 28.0);
    // Color by element (approximate by proton count)
    final Color nucleusColor = _nucleusColor(protons);
    canvas.drawCircle(Offset(cx, cy), nucleusR,
        Paint()..color = nucleusColor.withOpacity(0.3));
    canvas.drawCircle(
      Offset(cx, cy),
      nucleusR,
      Paint()
        ..color = nucleusColor
        ..strokeWidth = 2
        ..style = PaintingStyle.stroke,
    );

    // Draw electrons
    // Shell 1: angular speed 3 rad/s
    _drawElectrons(canvas, cx, cy, r1, shell1, t * 3.0, primaryColor);
    // Shell 2: angular speed 2 rad/s
    _drawElectrons(canvas, cx, cy, r2, shell2, t * 2.0, accentColor);
    // Shell 3: angular speed 1.2 rad/s
    _drawElectrons(canvas, cx, cy, r3, shell3, t * 1.2, successColor);

    // Labels
    _drawLabel(canvas, 'Z = $protons (protons)', Offset(8, 8), labelColor);
    _drawLabel(
        canvas, 'N = $neutrons', Offset(8, 22), labelColor);
    _drawLabel(
        canvas,
        'A = ${protons + neutrons}',
        Offset(8, 36),
        labelColor);
    final String symbol = _elementSymbol(protons);
    _drawLabel(
      canvas,
      symbol,
      Offset(cx - 8, cy - 10),
      textColor,
      fontSize: 14,
      bold: true,
    );
  }

  void _drawElectrons(Canvas canvas, double cx, double cy, double radius,
      int count, double baseAngle, Color color) {
    if (count <= 0) return;
    for (int i = 0; i < count; i++) {
      final double angle = baseAngle + (2 * math.pi * i / count);
      final double ex = cx + radius * math.cos(angle);
      final double ey = cy + radius * math.sin(angle);
      canvas.drawCircle(Offset(ex, ey), 5, Paint()..color = color);
    }
  }

  Color _nucleusColor(int protons) {
    if (protons <= 2) return const Color(0xFF90CAF9); // H/He
    if (protons <= 10) return const Color(0xFFA5D6A7); // Li-Ne
    if (protons <= 18) return const Color(0xFFFFCC80); // Na-Ar
    return const Color(0xFFEF9A9A); // K+
  }

  String _elementSymbol(int protons) {
    const symbols = [
      '', 'H', 'He', 'Li', 'Be', 'B', 'C', 'N', 'O', 'F', 'Ne',
      'Na', 'Mg', 'Al', 'Si', 'P', 'S', 'Cl', 'Ar',
    ];
    if (protons >= 1 && protons < symbols.length) return symbols[protons];
    return 'Z=$protons';
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color,
      {double fontSize = 10, bool bold = false}) {
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          color: color,
          fontSize: fontSize,
          fontWeight: bold ? FontWeight.w700 : FontWeight.normal,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(BohrModelRenderer old) =>
      old.state['_time'] != state['_time'] ||
      old.state['protons'] != state['protons'] ||
      old.state['neutrons'] != state['neutrons'] ||
      old.state['shell1'] != state['shell1'] ||
      old.state['shell2'] != state['shell2'] ||
      old.state['shell3'] != state['shell3'];
}

import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

class PopulationGrowthRenderer extends VisualTemplateRenderer {
  const PopulationGrowthRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double p0 =
        (state['initial_pop'] as num?)?.toDouble() ?? 100.0;
    final double r = (state['growth_rate'] as num?)?.toDouble() ?? 0.3;
    final double k =
        (state['carrying_capacity'] as num?)?.toDouble() ?? 1000.0;

    const double tMax = 30.0;
    const int samples = 200;
    const double padding = 40.0;

    final double plotLeft = padding;
    final double plotRight = size.width - padding * 0.5;
    final double plotTop = padding * 0.5;
    final double plotBottom = size.height - padding;

    final double yMax = k * 1.1;

    double toCanvasX(double t) =>
        plotLeft + (t / tMax) * (plotRight - plotLeft);
    double toCanvasY(double pop) =>
        plotBottom - (pop / yMax) * (plotBottom - plotTop);

    // Axes
    final axisPaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.5;
    canvas.drawLine(
        Offset(plotLeft, plotBottom), Offset(plotRight, plotBottom), axisPaint);
    canvas.drawLine(
        Offset(plotLeft, plotTop), Offset(plotLeft, plotBottom), axisPaint);

    // Tick marks and labels
    for (int tTick = 0; tTick <= 30; tTick += 5) {
      final double x = toCanvasX(tTick.toDouble());
      canvas.drawLine(Offset(x, plotBottom), Offset(x, plotBottom + 4),
          axisPaint);
      _drawLabel(canvas, '$tTick', Offset(x - 6, plotBottom + 5), labelColor);
    }
    for (int popTick = 0; popTick <= yMax.toInt(); popTick += (k / 4).round()) {
      final double y = toCanvasY(popTick.toDouble());
      canvas.drawLine(Offset(plotLeft - 4, y), Offset(plotLeft, y), axisPaint);
      _drawLabel(canvas, '$popTick', Offset(2, y - 6), labelColor,
          fontSize: 8);
    }

    // Axis labels
    _drawLabel(canvas, 't (years)', Offset(plotRight - 36, plotBottom + 12),
        labelColor);
    _drawLabel(canvas, 'P', Offset(4, plotTop), labelColor);

    // Carrying capacity dashed line
    final double kY = toCanvasY(k);
    final kPaint = Paint()
      ..color = successColor.withOpacity(0.7)
      ..strokeWidth = 1.0
      ..style = PaintingStyle.stroke;
    _drawDashedLine(
        canvas, Offset(plotLeft, kY), Offset(plotRight, kY), kPaint);
    _drawLabel(canvas, 'K=${k.toStringAsFixed(0)}',
        Offset(plotRight - 50, kY - 14), successColor);

    // Exponential growth (dashed, accentColor)
    final expPaint = Paint()
      ..color = accentColor.withOpacity(0.7)
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    final expPath = Path();
    bool firstExp = true;
    for (int i = 0; i <= samples; i++) {
      final double t = (i / samples) * tMax;
      double pop = p0 * math.exp(r * t);
      pop = pop.clamp(0.0, k * 1.2); // clamp
      final double cx = toCanvasX(t);
      final double cy = toCanvasY(pop.clamp(0.0, yMax));
      if (firstExp) {
        expPath.moveTo(cx, cy);
        firstExp = false;
      } else {
        expPath.lineTo(cx, cy);
      }
    }
    _drawDashedPath(canvas, expPath, expPaint);

    // Logistic growth (solid, primaryColor)
    final logPaint = Paint()
      ..color = primaryColor
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke;
    final logPath = Path();
    bool firstLog = true;
    for (int i = 0; i <= samples; i++) {
      final double t = (i / samples) * tMax;
      final double pop = _logistic(p0, r, k, t);
      final double cx = toCanvasX(t);
      final double cy = toCanvasY(pop.clamp(0.0, yMax));
      if (firstLog) {
        logPath.moveTo(cx, cy);
        firstLog = false;
      } else {
        logPath.lineTo(cx, cy);
      }
    }
    canvas.drawPath(logPath, logPaint);

    // Legend
    _drawLegendItem(canvas, primaryColor, 'Logistic', Offset(8, 8), solid: true);
    _drawLegendItem(canvas, accentColor, 'Exponential',
        Offset(8, 22), solid: false);
    _drawLabel(canvas, 'r=${r.toStringAsFixed(2)}/yr, P₀=${p0.toStringAsFixed(0)}',
        Offset(8, 36), labelColor);
  }

  double _logistic(double p0, double r, double k, double t) {
    if (p0 <= 0 || k <= 0) return 0;
    final double ratio = (k - p0) / p0;
    return k / (1 + ratio * math.exp(-r * t));
  }

  void _drawDashedLine(
      Canvas canvas, Offset start, Offset end, Paint paint) {
    const dashLen = 6.0;
    const gapLen = 4.0;
    final dir = end - start;
    final total = dir.distance;
    if (total == 0) return;
    final unit = dir / total;
    double pos = 0;
    while (pos < total) {
      final from = start + unit * pos;
      final to = start + unit * math.min(pos + dashLen, total);
      canvas.drawLine(from, to, paint);
      pos += dashLen + gapLen;
    }
  }

  void _drawDashedPath(Canvas canvas, Path path, Paint paint) {
    // Approximate: draw with dashed effect via PathMetrics
    final metrics = path.computeMetrics();
    const dashLen = 8.0;
    const gapLen = 5.0;
    for (final metric in metrics) {
      double pos = 0;
      while (pos < metric.length) {
        final end = math.min(pos + dashLen, metric.length);
        canvas.drawPath(metric.extractPath(pos, end), paint);
        pos += dashLen + gapLen;
      }
    }
  }

  void _drawLegendItem(Canvas canvas, Color color, String label, Offset pos,
      {required bool solid}) {
    final paint = Paint()
      ..color = color
      ..strokeWidth = 2.0
      ..style = PaintingStyle.stroke;
    if (solid) {
      canvas.drawLine(pos, Offset(pos.dx + 16, pos.dy + 6), paint);
    } else {
      _drawDashedLine(canvas, pos, Offset(pos.dx + 16, pos.dy + 6), paint);
    }
    _drawLabel(canvas, label, Offset(pos.dx + 18, pos.dy), color);
  }

  void _drawLabel(Canvas canvas, String text, Offset offset, Color color,
      {double fontSize = 10}) {
    final tp = TextPainter(
      text: TextSpan(
          text: text, style: TextStyle(color: color, fontSize: fontSize)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, offset);
  }

  @override
  bool shouldRepaint(PopulationGrowthRenderer old) =>
      old.state['initial_pop'] != state['initial_pop'] ||
      old.state['growth_rate'] != state['growth_rate'] ||
      old.state['carrying_capacity'] != state['carrying_capacity'];
}

import 'package:flutter/material.dart';
import 'renderers/sorting_bars_renderer.dart';
import 'renderers/function_plot_renderer.dart';
import 'renderers/unit_circle_renderer.dart';
import 'renderers/ideal_gas_piston_renderer.dart';
import 'renderers/projectile_renderer.dart';
import 'renderers/pendulum_renderer.dart';
import 'renderers/wave_renderer.dart';
import 'renderers/pythagorean_renderer.dart';
import 'renderers/spring_mass_renderer.dart';
import 'renderers/ohms_law_renderer.dart';
import 'renderers/derivative_renderer.dart';
import 'renderers/bohr_model_renderer.dart';
import 'renderers/population_growth_renderer.dart';

class VisualRendererFactory {
  VisualRendererFactory._();

  static CustomPainter? create({
    required String templateFamily,
    required Map<String, dynamic> state,
    required Map<String, dynamic> scene,
    required bool isDark,
    Listenable? repaint,
  }) {
    switch (templateFamily) {
      case 'sorting-bars':
        return SortingBarsRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'function-plot':
        return FunctionPlotRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'unit-circle':
        return UnitCircleRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ideal-gas-piston':
        return IdealGasPistonRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'projectile':
        return ProjectileRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pendulum':
        return PendulumRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'wave':
        return WaveRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pythagorean':
        return PythagoreanRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'spring-mass':
        return SpringMassRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ohms-law':
        return OhmsLawRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'derivative':
        return DerivativeRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'bohr-model':
        return BohrModelRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'population-growth':
        return PopulationGrowthRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      default:
        return null;
    }
  }

  /// Returns the simulation step function for a template, or null if not a simulation.
  static void Function(Map<String, dynamic> state, double dt)? simulationStepFor(
    String templateFamily,
  ) {
    switch (templateFamily) {
      case 'unit-circle':
        return UnitCircleRenderer.simulationStep;
      case 'projectile':
        return ProjectileRenderer.simulationStep;
      case 'pendulum':
        return PendulumRenderer.simulationStep;
      case 'wave':
        return WaveRenderer.simulationStep;
      case 'spring-mass':
        return SpringMassRenderer.simulationStep;
      case 'bohr-model':
        return BohrModelRenderer.simulationStep;
      default:
        return null;
    }
  }

  /// Returns the 'play' handler for a template (e.g., projectile launch)
  static void Function(Map<String, dynamic> state)? playHandlerFor(
      String templateFamily) {
    switch (templateFamily) {
      case 'projectile':
        return ProjectileRenderer.launch;
      case 'pendulum':
        return PendulumRenderer.launch;
      case 'spring-mass':
        return SpringMassRenderer.launch;
      default:
        return null;
    }
  }
}

