import 'package:flutter/material.dart';
import 'renderers/sorting_bars_renderer.dart';
import 'renderers/function_plot_renderer.dart';
import 'renderers/unit_circle_renderer.dart';
import 'renderers/ideal_gas_piston_renderer.dart';
import 'renderers/projectile_renderer.dart';
import 'renderers/pendulum_renderer.dart';
import 'renderers/wave_renderer.dart';
import 'renderers/pythagorean_renderer.dart';
import 'renderers/spring_mass_renderer.dart';
import 'renderers/ohms_law_renderer.dart';
import 'renderers/derivative_renderer.dart';
import 'renderers/bohr_model_renderer.dart';
import 'renderers/population_growth_renderer.dart';

class VisualRendererFactory {
  VisualRendererFactory._();

  static CustomPainter? create({
    required String templateFamily,
    required Map<String, dynamic> state,
    required Map<String, dynamic> scene,
    required bool isDark,
    Listenable? repaint,
  }) {
    switch (templateFamily) {
      case 'sorting-bars':
        return SortingBarsRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'function-plot':
        return FunctionPlotRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'unit-circle':
        return UnitCircleRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ideal-gas-piston':
        return IdealGasPistonRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'projectile':
        return ProjectileRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pendulum':
        return PendulumRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'wave':
        return WaveRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pythagorean':
        return PythagoreanRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'spring-mass':
        return SpringMassRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ohms-law':
        return OhmsLawRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'derivative':
        return DerivativeRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'bohr-model':
        return BohrModelRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'population-growth':
        return PopulationGrowthRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      default:
        return null;
    }
  }

  /// Returns the simulation step function for a template, or null if not a simulation.
  static void Function(Map<String, dynamic> state, double dt)? simulationStepFor(
    String templateFamily,
  ) {
    switch (templateFamily) {
      case 'unit-circle':
        return UnitCircleRenderer.simulationStep;
      case 'projectile':
        return ProjectileRenderer.simulationStep;
      case 'pendulum':
        return PendulumRenderer.simulationStep;
      case 'wave':
        return WaveRenderer.simulationStep;
      case 'spring-mass':
        return SpringMassRenderer.simulationStep;
      case 'bohr-model':
        return BohrModelRenderer.simulationStep;
      default:
        return null;
    }
  }

  /// Returns the 'play' handler for a template (e.g., projectile launch)
  static void Function(Map<String, dynamic> state)? playHandlerFor(
      String templateFamily) {
    switch (templateFamily) {
      case 'projectile':
        return ProjectileRenderer.launch;
      case 'pendulum':
        return PendulumRenderer.launch;
      case 'spring-mass':
        return SpringMassRenderer.launch;
      default:
        return null;
    }
  }
}

