      ..color = axisColor.withOpacity(0.25)
      ..strokeWidth = 0.5;
    for (int gx = xMin.ceil(); gx <= xMax.floor(); gx++) {
      final cx = toCanvasX(gx.toDouble());
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), gridPaint);
    }
    for (int gy = yMin.ceil(); gy <= yMax.floor(); gy++) {
      final cy = toCanvasY(gy.toDouble());
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), gridPaint);
    }

    // Axes
    final axisPaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.0;
    if (xMin <= 0 && xMax >= 0) {
      final cx = toCanvasX(0);
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), axisPaint);
    }
    if (yMin <= 0 && yMax >= 0) {
      final cy = toCanvasY(0);
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), axisPaint);
    }

    // Trails for N-body bodies
    const trailColors = [
      Color(0xFF58A6FF),
      Color(0xFFFFA657),
      Color(0xFF3FB950),
      Color(0xFFFF7B72),
      Color(0xFFAA55FF),
    ];
    final bodyCount = _detectBodyCount(state);
    for (int i = 0; i < bodyCount; i++) {
      final trail = (state['_trail_body${i + 1}'] as List?)
              ?.map((e) => Map<String, double>.from(e as Map))
              .toList() ??
          [];
      if (trail.length > 1) {
        final path = Path();
        path.moveTo(
          toCanvasX(trail.first['x']!),
          toCanvasY(trail.first['y']!),
        );
        for (final pt in trail.skip(1)) {
          path.lineTo(toCanvasX(pt['x']!), toCanvasY(pt['y']!));
        }
        canvas.drawPath(
          path,
          Paint()
            ..color = trailColors[i % trailColors.length].withOpacity(0.45)
            ..strokeWidth = 1.5
            ..style = PaintingStyle.stroke,
        );
      }
    }

    // Scene objects: iterate named entries whose value is a Map with a `type` key
    for (final entry in scene.entries) {
      final obj = entry.value;
      if (obj is! Map) continue;
      final objMap = Map<String, dynamic>.from(obj);
      final type = objMap['type'] as String? ?? 'circle';
      final color = _parseColor(objMap['color'], primaryColor);

      switch (type) {
        case 'circle':
          final wx = _resolve(objMap['x']);
          final wy = _resolve(objMap['y']);
          final rawR = (objMap['radius'] as num?)?.toDouble() ?? 0.2;
          final canvasR = scaleR(rawR).clamp(3.0, 30.0);
          canvas.drawCircle(
            Offset(toCanvasX(wx), toCanvasY(wy)),
            canvasR,
            Paint()..color = color,
          );
          // Subtle glow
          canvas.drawCircle(
            Offset(toCanvasX(wx), toCanvasY(wy)),
            canvasR * 1.6,
            Paint()..color = color.withOpacity(0.15),
          );
          // Label
          final label = objMap['label'] as String?;
          if (label != null || entry.key.startsWith('body')) {
            final displayLabel = label ?? entry.key;
            final tp = TextPainter(
              text: TextSpan(
                text: displayLabel,
                style: TextStyle(
                  color: textColor,
                  fontSize: 9,
                  fontWeight: FontWeight.w600,
                ),
              ),
              textDirection: TextDirection.ltr,
            )..layout();
            tp.paint(
              canvas,
              Offset(
                toCanvasX(wx) + canvasR + 3,
                toCanvasY(wy) - 5,
              ),
            );
          }

        case 'rectangle':
        case 'rect':
          final wx = _resolve(objMap['x']);
          final wy = _resolve(objMap['y']);
          final w = (objMap['width'] as num?)?.toDouble() ?? 1.0;
          final h = (objMap['height'] as num?)?.toDouble() ?? 1.0;
          canvas.drawRect(
            Rect.fromCenter(
              center: Offset(toCanvasX(wx), toCanvasY(wy)),
              width: scaleR(w),
              height: h / worldH * drawH,
            ),
            Paint()..color = color.withOpacity(0.7),
          );

        case 'arrow':
        case 'line':
          final x1 = _resolve(objMap['x1'] ?? objMap['x']);
