            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pendulum':
        return PendulumRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'wave':
        return WaveRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'pythagorean':
        return PythagoreanRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'spring-mass':
        return SpringMassRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'ohms-law':
        return OhmsLawRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'derivative':
        return DerivativeRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'bohr-model':
        return BohrModelRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      case 'population-growth':
        return PopulationGrowthRenderer(
            state: state, scene: scene, isDark: isDark, repaint: repaint);
      default:
        return null;
    }
  }

  /// Returns the simulation step function for a template, or null if not a simulation.
  static void Function(Map<String, dynamic> state, double dt)? simulationStepFor(
    String templateFamily,
