        return UnitCircleRenderer.simulationStep;
      case 'projectile':
        return ProjectileRenderer.simulationStep;
      case 'pendulum':
        return PendulumRenderer.simulationStep;
      case 'wave':
        return WaveRenderer.simulationStep;
      case 'spring-mass':
        return SpringMassRenderer.simulationStep;
      case 'bohr-model':
        return BohrModelRenderer.simulationStep;
      default:
        return null;
    }
  }

  /// Returns the 'play' handler for a template (e.g., projectile launch)
  static void Function(Map<String, dynamic> state)? playHandlerFor(
      String templateFamily) {
    switch (templateFamily) {
      case 'projectile':
        return ProjectileRenderer.launch;
      case 'pendulum':
        return PendulumRenderer.launch;
      case 'spring-mass':
        return SpringMassRenderer.launch;
      default:
        return null;
    }
  }
}

