/// Compute a viewport that includes all scene objects and all body positions.
/// Expands `scene.xMin/xMax/yMin/yMax` if any object falls outside it.
List<double> _computeViewport() {
  double xMin = (scene['xMin'] as num?)?.toDouble() ?? -5.0;
  double xMax = (scene['xMax'] as num?)?.toDouble() ?? 5.0;
  double yMin = (scene['yMin'] as num?)?.toDouble() ?? -5.0;
  double yMax = (scene['yMax'] as num?)?.toDouble() ?? 5.0;

  // Expand to include all body positions from state.
  final bodyCount = _detectBodyCount(state);
  for (int i = 1; i <= bodyCount; i++) {
    final x = (state['body${i}_x'] as num?)?.toDouble();
    final y = (state['body${i}_y'] as num?)?.toDouble();
    if (x != null) {
      if (x < xMin) xMin = x - 0.5;
      if (x > xMax) xMax = x + 0.5;
    }
    if (y != null) {
      if (y < yMin) yMin = y - 0.5;
      if (y > yMax) yMax = y + 0.5;
    }
  }

  // Also expand to include scene objects whose positions are literal numbers.
  for (final entry in scene.entries) {
    final obj = entry.value;
    if (obj is! Map) continue;
    final x = obj['x'];
    final y = obj['y'];
    if (x is num) {
      if (x.toDouble() < xMin) xMin = x.toDouble() - 0.5;
      if (x.toDouble() > xMax) xMax = x.toDouble() + 0.5;
    }
    if (y is num) {
      if (y.toDouble() < yMin) yMin = y.toDouble() - 0.5;
      if (y.toDouble() > yMax) yMax = y.toDouble() + 0.5;
    }
  }

  // Ensure square-ish aspect ratio — prevents extreme distortion.
  final worldW = xMax - xMin;
  final worldH = yMax - yMin;
  if (worldW <= 0 || worldH <= 0) return [-5.0, 5.0, -5.0, 5.0];
  return [xMin, xMax, yMin, yMax];
}

