import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

/// Generic scene renderer that interprets AI-generated scene definitions.
///
/// Scene objects are named entries in `scene` where the value is a Map
/// containing a `type` key. Supported types: circle, rectangle/rect,
/// line, arrow.
///
/// Position values can be literal numbers or strings referencing a state key
/// (e.g. `"x": "body1_x"` → resolved from `state['body1_x']`).
///
/// Auto-detects N-body systems from state keys matching `body{N}_x`,
/// `body{N}_y`, `body{N}_vx`, `body{N}_vy`, `body{N}_mass` and applies
/// Newtonian gravitational physics (F = G·m1·m2 / r²) with softening.
class GenericSceneRenderer extends VisualTemplateRenderer {
  static const double _G = 1.0;
  static const double _softening = 0.15;

  const GenericSceneRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  // ─── Static helpers ────────────────────────────────────────────────────────

  static int _detectBodyCount(Map<String, dynamic> state) {
    int count = 0;
    for (int i = 1; i <= 20; i++) {
      if (state.containsKey('body${i}_x')) {
        count = i;
      } else {
        break;
      }
    }
    return count;
  }

  static void simulationStep(Map<String, dynamic> state, double dt) {
    final bodyCount = _detectBodyCount(state);
    if (bodyCount < 2) return;

    // Accumulate pairwise gravitational forces.
    final forces = List.generate(bodyCount, (_) => [0.0, 0.0]);
    for (int i = 0; i < bodyCount; i++) {
      final xi = (state['body${i + 1}_x'] as num?)?.toDouble() ?? 0.0;
      final yi = (state['body${i + 1}_y'] as num?)?.toDouble() ?? 0.0;
      final mi = (state['body${i + 1}_mass'] as num?)?.toDouble() ?? 1.0;
      for (int j = i + 1; j < bodyCount; j++) {
        final xj = (state['body${j + 1}_x'] as num?)?.toDouble() ?? 0.0;
        final yj = (state['body${j + 1}_y'] as num?)?.toDouble() ?? 0.0;
        final mj = (state['body${j + 1}_mass'] as num?)?.toDouble() ?? 1.0;
        final dx = xj - xi;
        final dy = yj - yi;
        final r2 = dx * dx + dy * dy + _softening * _softening;
        final r = math.sqrt(r2);
        final f = _G * mi * mj / r2;
        final fx = f * dx / r;
        final fy = f * dy / r;
        forces[i][0] += fx;
        forces[i][1] += fy;
        forces[j][0] -= fx;
        forces[j][1] -= fy;
      }
    }

    // Euler integration + trail update.
    for (int i = 0; i < bodyCount; i++) {
      final key = 'body${i + 1}';
      final m = (state['${key}_mass'] as num?)?.toDouble() ?? 1.0;
      double vx = (state['${key}_vx'] as num?)?.toDouble() ?? 0.0;
      double vy = (state['${key}_vy'] as num?)?.toDouble() ?? 0.0;
      double x = (state['${key}_x'] as num?)?.toDouble() ?? 0.0;
      double y = (state['${key}_y'] as num?)?.toDouble() ?? 0.0;
      vx += (forces[i][0] / m) * dt;
      vy += (forces[i][1] / m) * dt;
      x += vx * dt;
      y += vy * dt;
      state['${key}_vx'] = vx;
      state['${key}_vy'] = vy;
      state['${key}_x'] = x;
      state['${key}_y'] = y;
      // Trail
      final trailKey = '_trail_$key';
      final trail = List<Map<String, double>>.from(
        (state[trailKey] as List?)
                ?.map((e) => Map<String, double>.from(e as Map)) ??
            [],
      );
      trail.add({'x': x, 'y': y});
      if (trail.length > 150) trail.removeAt(0);
      state[trailKey] = trail;
    }
  }

  // ─── Instance helpers ──────────────────────────────────────────────────────

  double _resolve(dynamic val, [double fallback = 0.0]) {
    if (val is num) return val.toDouble();
    if (val is String) return (state[val] as num?)?.toDouble() ?? fallback;
    return fallback;
  }

  static Color _parseColor(dynamic val, Color fallback) {
    if (val is! String) return fallback;
    const colorMap = {
      'red': Color(0xFFFF5555),
      'blue': Color(0xFF5599FF),
      'green': Color(0xFF55CC77),
      'yellow': Color(0xFFFFDD44),
      'orange': Color(0xFFFF8833),
      'purple': Color(0xFFAA55FF),
      'cyan': Color(0xFF55DDEE),
      'white': Colors.white,
      'black': Colors.black,
      'gray': Color(0xFF888888),
      'grey': Color(0xFF888888),
    };
    final lower = val.toLowerCase();
    if (colorMap.containsKey(lower)) return colorMap[lower]!;
    if (val.startsWith('#') && val.length == 7) {
      try {
        return Color(int.parse('FF${val.substring(1)}', radix: 16));
      } catch (_) {}
    }
    return fallback;
  }

  // ─── Paint ─────────────────────────────────────────────────────────────────

  @override
  void paint(Canvas canvas, Size size) {
    final xMin = (scene['xMin'] as num?)?.toDouble() ?? -5.0;
    final xMax = (scene['xMax'] as num?)?.toDouble() ?? 5.0;
    final yMin = (scene['yMin'] as num?)?.toDouble() ?? -5.0;
    final yMax = (scene['yMax'] as num?)?.toDouble() ?? 5.0;
    final worldW = xMax - xMin;
    final worldH = yMax - yMin;
    const pad = 24.0;
    final drawW = size.width - pad * 2;
    final drawH = size.height - pad * 2;

    double toCanvasX(double wx) => pad + (wx - xMin) / worldW * drawW;
    double toCanvasY(double wy) => pad + (yMax - wy) / worldH * drawH;
    double scaleR(double wr) => wr / worldW * drawW;

    // Grid
    final gridPaint = Paint()
      ..color = axisColor.withOpacity(0.25)
      ..strokeWidth = 0.5;
    for (int gx = xMin.ceil(); gx <= xMax.floor(); gx++) {
      final cx = toCanvasX(gx.toDouble());
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), gridPaint);
    }
    for (int gy = yMin.ceil(); gy <= yMax.floor(); gy++) {
      final cy = toCanvasY(gy.toDouble());
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), gridPaint);
    }

    // Axes
    final axisPaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.0;
    if (xMin <= 0 && xMax >= 0) {
      final cx = toCanvasX(0);
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), axisPaint);
    }
    if (yMin <= 0 && yMax >= 0) {
      final cy = toCanvasY(0);
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), axisPaint);
    }

    // Trails for N-body bodies
    const trailColors = [
      Color(0xFF58A6FF),
      Color(0xFFFFA657),
      Color(0xFF3FB950),
      Color(0xFFFF7B72),
      Color(0xFFAA55FF),
    ];
    final bodyCount = _detectBodyCount(state);
    for (int i = 0; i < bodyCount; i++) {
      final trail = (state['_trail_body${i + 1}'] as List?)
              ?.map((e) => Map<String, double>.from(e as Map))
              .toList() ??
          [];
      if (trail.length > 1) {
        final path = Path();
        path.moveTo(
          toCanvasX(trail.first['x']!),
          toCanvasY(trail.first['y']!),
        );
        for (final pt in trail.skip(1)) {
          path.lineTo(toCanvasX(pt['x']!), toCanvasY(pt['y']!));
        }
        canvas.drawPath(
          path,
          Paint()
            ..color = trailColors[i % trailColors.length].withOpacity(0.45)
            ..strokeWidth = 1.5
            ..style = PaintingStyle.stroke,
        );
      }
    }

    // Scene objects: iterate named entries whose value is a Map with a `type` key
    for (final entry in scene.entries) {
      final obj = entry.value;
      if (obj is! Map) continue;
      final objMap = Map<String, dynamic>.from(obj);
      final type = objMap['type'] as String? ?? 'circle';
      final color = _parseColor(objMap['color'], primaryColor);

      switch (type) {
        case 'circle':
          final wx = _resolve(objMap['x']);
          final wy = _resolve(objMap['y']);
          final rawR = (objMap['radius'] as num?)?.toDouble() ?? 0.2;
          final canvasR = scaleR(rawR).clamp(3.0, 30.0);
          canvas.drawCircle(
            Offset(toCanvasX(wx), toCanvasY(wy)),
            canvasR,
            Paint()..color = color,
          );
          // Subtle glow
          canvas.drawCircle(
            Offset(toCanvasX(wx), toCanvasY(wy)),
            canvasR * 1.6,
            Paint()..color = color.withOpacity(0.15),
          );
          // Label
          final label = objMap['label'] as String?;
          if (label != null || entry.key.startsWith('body')) {
            final displayLabel = label ?? entry.key;
            final tp = TextPainter(
              text: TextSpan(
                text: displayLabel,
                style: TextStyle(
                  color: textColor,
                  fontSize: 9,
                  fontWeight: FontWeight.w600,
                ),
              ),
              textDirection: TextDirection.ltr,
            )..layout();
            tp.paint(
              canvas,
              Offset(
                toCanvasX(wx) + canvasR + 3,
                toCanvasY(wy) - 5,
              ),
            );
          }

        case 'rectangle':
        case 'rect':
          final wx = _resolve(objMap['x']);
          final wy = _resolve(objMap['y']);
          final w = (objMap['width'] as num?)?.toDouble() ?? 1.0;
          final h = (objMap['height'] as num?)?.toDouble() ?? 1.0;
          canvas.drawRect(
            Rect.fromCenter(
              center: Offset(toCanvasX(wx), toCanvasY(wy)),
              width: scaleR(w),
              height: h / worldH * drawH,
            ),
            Paint()..color = color.withOpacity(0.7),
          );

        case 'arrow':
        case 'line':
          final x1 = _resolve(objMap['x1'] ?? objMap['x']);
          final y1 = _resolve(objMap['y1'] ?? objMap['y']);
          final x2 = _resolve(objMap['x2']);
          final y2 = _resolve(objMap['y2']);
          final p1 = Offset(toCanvasX(x1), toCanvasY(y1));
          final p2 = Offset(toCanvasX(x2), toCanvasY(y2));
          canvas.drawLine(p1, p2, Paint()..color = color..strokeWidth = 2.0);
          if (type == 'arrow') _drawArrowHead(canvas, p1, p2, color);
      }
    }
  }

  void _drawArrowHead(Canvas canvas, Offset from, Offset to, Color color) {
    final angle = math.atan2(to.dy - from.dy, to.dx - from.dx);
    const len = 10.0;
    const spread = 0.4;
    final p1 = Offset(
      to.dx - len * math.cos(angle - spread),
      to.dy - len * math.sin(angle - spread),
    );
    final p2 = Offset(
      to.dx - len * math.cos(angle + spread),
      to.dy - len * math.sin(angle + spread),
    );
    final paint = Paint()
      ..color = color
      ..strokeWidth = 2.0;
    canvas.drawLine(to, p1, paint);
    canvas.drawLine(to, p2, paint);
  }

  @override
  bool shouldRepaint(GenericSceneRenderer old) {
    if (old.state.length != state.length) return true;
    for (final key in state.keys) {
      if (old.state[key] != state[key]) return true;
    }
    return false;
  }
}

