  double xMin = (scene['xMin'] as num?)?.toDouble() ?? -5.0;
  double xMax = (scene['xMax'] as num?)?.toDouble() ?? 5.0;
  double yMin = (scene['yMin'] as num?)?.toDouble() ?? -5.0;
  double yMax = (scene['yMax'] as num?)?.toDouble() ?? 5.0;

