  final bodyCount = _detectBodyCount(state);
  for (int i = 1; i <= bodyCount; i++) {
    final x = (state['body${i}_x'] as num?)?.toDouble();
    final y = (state['body${i}_y'] as num?)?.toDouble();
    if (x != null) {
      if (x < xMin) xMin = x - 0.5;
      if (x > xMax) xMax = x + 0.5;
    }
    if (y != null) {
      if (y < yMin) yMin = y - 0.5;
      if (y > yMax) yMax = y + 0.5;
    }
  }

  // Also expand to include scene objects whose positions are literal numbers.
  for (final entry in scene.entries) {
    final obj = entry.value;
    if (obj is! Map) continue;
    final x = obj['x'];
    final y = obj['y'];
