      if (y.toDouble() < yMin) yMin = y.toDouble() - 0.5;
      if (y.toDouble() > yMax) yMax = y.toDouble() + 0.5;
    }
  }

  if (xMax - xMin <= 0 || yMax - yMin <= 0) return [-5.0, 5.0, -5.0, 5.0];
  return [xMin, xMax, yMin, yMax];
}

