import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../visual_template_renderer.dart';

/// Generic scene renderer that interprets AI-generated scene definitions.
///
/// Scene objects are named entries in `scene` where the value is a Map
/// containing a `type` key. Supported types: circle, rectangle/rect,
/// line, arrow.
///
/// Position values can be literal numbers or strings referencing a state key
/// (e.g. `"x": "body1_x"` → resolved from `state['body1_x']`).
///
/// Auto-detects N-body systems from state keys matching `body{N}_x`,
/// `body{N}_y`, `body{N}_vx`, `body{N}_vy`, `body{N}_mass` and applies
/// Newtonian gravitational physics (F = G·m1·m2 / r²) with softening.
class GenericSceneRenderer extends VisualTemplateRenderer {
  static const double _G = 1.0;
  static const double _softening = 0.15;

  const GenericSceneRenderer({
    required super.state,
    required super.scene,
    required super.isDark,
    super.repaint,
  });

  // ─── Static helpers ────────────────────────────────────────────────────────

  static int _detectBodyCount(Map<String, dynamic> state) {
    int count = 0;
    for (int i = 1; i <= 20; i++) {
      if (state.containsKey('body${i}_x')) {
        count = i;
      } else {
        break;
      }
    }
    return count;
  }

  static void simulationStep(Map<String, dynamic> state, double dt) {
    final bodyCount = _detectBodyCount(state);
    if (bodyCount < 2) return;

    // Accumulate pairwise gravitational forces.
    final forces = List.generate(bodyCount, (_) => [0.0, 0.0]);
    for (int i = 0; i < bodyCount; i++) {
      final xi = (state['body${i + 1}_x'] as num?)?.toDouble() ?? 0.0;
      final yi = (state['body${i + 1}_y'] as num?)?.toDouble() ?? 0.0;
      final mi = (state['body${i + 1}_mass'] as num?)?.toDouble() ?? 1.0;
      for (int j = i + 1; j < bodyCount; j++) {
        final xj = (state['body${j + 1}_x'] as num?)?.toDouble() ?? 0.0;
        final yj = (state['body${j + 1}_y'] as num?)?.toDouble() ?? 0.0;
        final mj = (state['body${j + 1}_mass'] as num?)?.toDouble() ?? 1.0;
        final dx = xj - xi;
        final dy = yj - yi;
        final r2 = dx * dx + dy * dy + _softening * _softening;
        final r = math.sqrt(r2);
        final f = _G * mi * mj / r2;
        final fx = f * dx / r;
        final fy = f * dy / r;
        forces[i][0] += fx;
        forces[i][1] += fy;
        forces[j][0] -= fx;
        forces[j][1] -= fy;
      }
    }

    // Euler integration + trail update.
    for (int i = 0; i < bodyCount; i++) {
      final key = 'body${i + 1}';
      final m = (state['${key}_mass'] as num?)?.toDouble() ?? 1.0;
      double vx = (state['${key}_vx'] as num?)?.toDouble() ?? 0.0;
      double vy = (state['${key}_vy'] as num?)?.toDouble() ?? 0.0;
      double x = (state['${key}_x'] as num?)?.toDouble() ?? 0.0;
      double y = (state['${key}_y'] as num?)?.toDouble() ?? 0.0;
      vx += (forces[i][0] / m) * dt;
      vy += (forces[i][1] / m) * dt;
      x += vx * dt;
      y += vy * dt;
      state['${key}_vx'] = vx;
      state['${key}_vy'] = vy;
      state['${key}_x'] = x;
      state['${key}_y'] = y;
      // Trail
      final trailKey = '_trail_$key';
      final trail = List<Map<String, double>>.from(
        (state[trailKey] as List?)
                ?.map((e) => Map<String, double>.from(e as Map)) ??
            [],
      );
      trail.add({'x': x, 'y': y});
      if (trail.length > 150) trail.removeAt(0);
      state[trailKey] = trail;
    }
  }

  // ─── Instance helpers ──────────────────────────────────────────────────────

  double _resolve(dynamic val, [double fallback = 0.0]) {
    if (val is num) return val.toDouble();
    if (val is String) return (state[val] as num?)?.toDouble() ?? fallback;
    return fallback;
  }

  static Color _parseColor(dynamic val, Color fallback) {
    if (val is! String) return fallback;
    const colorMap = {
      'red': Color(0xFFFF5555),
      'blue': Color(0xFF5599FF),
      'green': Color(0xFF55CC77),
      'yellow': Color(0xFFFFDD44),
      'orange': Color(0xFFFF8833),
      'purple': Color(0xFFAA55FF),
      'cyan': Color(0xFF55DDEE),
      'white': Colors.white,
      'black': Colors.black,
      'gray': Color(0xFF888888),
      'grey': Color(0xFF888888),
    };
