      final cx = toCanvasX(gx.toDouble());
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), gridPaint);
    }
    for (int gy = yMin.ceil(); gy <= yMax.floor(); gy++) {
      final cy = toCanvasY(gy.toDouble());
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), gridPaint);
    }

    // Axes
    final axisPaint = Paint()
      ..color = axisColor
      ..strokeWidth = 1.0;
    if (xMin <= 0 && xMax >= 0) {
      final cx = toCanvasX(0);
      canvas.drawLine(Offset(cx, pad), Offset(cx, size.height - pad), axisPaint);
    }
    if (yMin <= 0 && yMax >= 0) {
      final cy = toCanvasY(0);
      canvas.drawLine(Offset(pad, cy), Offset(size.width - pad, cy), axisPaint);
    }

    // Trails for N-body bodies
    const trailColors = [
      Color(0xFF58A6FF),
      Color(0xFFFFA657),
      Color(0xFF3FB950),
      Color(0xFFFF7B72),
      Color(0xFFAA55FF),
