        case 'arrow':
        case 'line':
          final x1 = _resolve(objMap['x1'] ?? objMap['x']);
          final y1 = _resolve(objMap['y1'] ?? objMap['y']);
          final x2 = _resolve(objMap['x2']);
          final y2 = _resolve(objMap['y2']);
          final p1 = Offset(toCanvasX(x1), toCanvasY(y1));
          final p2 = Offset(toCanvasX(x2), toCanvasY(y2));
          canvas.drawLine(p1, p2, Paint()..color = color..strokeWidth = 2.0);
          if (type == 'arrow') _drawArrowHead(canvas, p1, p2, color);
      }
    }
  }

  void _drawArrowHead(Canvas canvas, Offset from, Offset to, Color color) {
    final angle = math.atan2(to.dy - from.dy, to.dx - from.dx);
    const len = 10.0;
    const spread = 0.4;
    final p1 = Offset(
      to.dx - len * math.cos(angle - spread),
      to.dy - len * math.sin(angle - spread),
    );
    final p2 = Offset(
      to.dx - len * math.cos(angle + spread),
      to.dy - len * math.sin(angle + spread),
    );
    final paint = Paint()
      ..color = color
      ..strokeWidth = 2.0;
    canvas.drawLine(to, p1, paint);
    canvas.drawLine(to, p2, paint);
  }

  @override
  bool shouldRepaint(GenericSceneRenderer old) {
    if (old.state.length != state.length) return true;
    for (final key in state.keys) {
      if (old.state[key] != state[key]) return true;
    }
    return false;
  }
}

