import 'package:supabase_flutter/supabase_flutter.dart';
import '../models/models.dart';

/// Generation stages for the staged UX
enum VisualGenerationStage { idle, analyzing, generatingScene, done, error }

enum VisualGenerationRoute { sceneSpec, htmlFallback }

/// Result of an AI visual generation request
class VisualGenerationResult {
  final InteractiveVisualContent? spec;
  final String? error;
  final VisualGenerationRoute? route;

  const VisualGenerationResult({this.spec, this.error, this.route});
  bool get isSuccess => spec != null && error == null;
  bool get usedHtmlFallback => route == VisualGenerationRoute.htmlFallback;
}

/// AI visual generator — calls the Supabase Edge Function `gemini-generate`.
/// The Gemini API key is stored as a server-side secret; the client never sees it.
class AIVisualGenerator {
  AIVisualGenerator._();

  static final _client = Supabase.instance.client;

  /// Generate an interactive visual from a natural language [prompt].
  static Future<VisualGenerationResult> generate({
    required String prompt,
  }) async {
    try {
      final response = await _client.functions.invoke(
        'gemini-generate',
        body: {'prompt': prompt},
      );

      final data = response.data as Map<String, dynamic>?;
      final routeRaw = data?['route'] as String?;
      final route = _parseRoute(routeRaw);
      final specRaw = data?['spec'];
      final htmlRaw = data?['html'];
      final metaRaw = data?['meta'];

      if (data?['error'] is String) {
        return VisualGenerationResult(
          error: _formatGenerationErrorPayload(data!),
          route: route,
        );
      }

      if (specRaw is Map) {
        final specMap = Map<String, dynamic>.from(specRaw);
        final generationMeta = specMap['generationMeta'] is Map
            ? Map<String, dynamic>.from(specMap['generationMeta'] as Map)
            : <String, dynamic>{};
        generationMeta['route'] = routeRaw ?? 'scene-spec';
        specMap['generationMeta'] = generationMeta;
        specMap['aiPrompt'] = prompt;
        final spec = InteractiveVisualContent.fromJson(specMap);
        return VisualGenerationResult(spec: spec, route: route);
      }

      if (htmlRaw is String && htmlRaw.trim().isNotEmpty) {
        final meta = metaRaw is Map
            ? Map<String, dynamic>.from(metaRaw)
            : <String, dynamic>{};
        final generationMeta = <String, dynamic>{
          'route': routeRaw ?? 'html-fallback',
          'fallbackReason': meta['fallbackReason'],
          if (meta['specTemplateChoice'] != null)
            'templateChoice': meta['specTemplateChoice'],
          if (meta['specConfidence'] != null)
            'confidence': meta['specConfidence'],
          if (meta['specWarnings'] is List) 'warnings': meta['specWarnings'],
        };
        final content = InteractiveVisualContent(
          version: InteractiveVisualContent.engineVersionHtml,
          engine: VisualEngine.htmlRuntime,
          title: meta['title'] as String? ?? _inferTitleFromPrompt(prompt),
          description: meta['description'] as String?,
          aiPrompt: prompt,
          generationMeta: generationMeta,
          htmlRuntime: VisualHtmlRuntime(
            html: htmlRaw,
            height: (meta['height'] as num?)?.toDouble() ?? 420,
            source: meta['source'] as String? ?? 'html-fallback',
          ),
        );
        return VisualGenerationResult(spec: content, route: route);
      }

      if (specRaw == null || specRaw is! Map) {
        final errorPayload = data ?? const <String, dynamic>{};
        final error = _formatGenerationErrorPayload(errorPayload);
        return VisualGenerationResult(error: error, route: route);
      }

      return VisualGenerationResult(
        error: 'AI returned an unsupported visual payload.',
        route: route,
      );
    } on FunctionException catch (e) {
      if (e.details is Map) {
        return VisualGenerationResult(
          error: _formatGenerationErrorPayload(
            Map<String, dynamic>.from(e.details as Map),
          ),
        );
      }
      return VisualGenerationResult(
        error:
            e.details?.toString() ?? 'Edge Function error: ${e.reasonPhrase}',
      );
    } catch (e) {
      return VisualGenerationResult(error: e.toString());
    }
  }

  static String _inferTitleFromPrompt(String prompt) {
    final cleaned = prompt
        .replaceFirst(
          RegExp(r'^PREFERRED TEMPLATE:[^\n]*\n+', caseSensitive: false),
          '',
        )
        .replaceFirst(RegExp(r'^CONTENT:\s*', caseSensitive: false), '')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    if (cleaned.isEmpty) return 'Interactive Visual';
    final words = cleaned.split(' ').take(7).join(' ');
    return words.length > 52 ? '${words.substring(0, 49).trim()}...' : words;
  }

  static VisualGenerationRoute? _parseRoute(String? routeRaw) {
    switch (routeRaw) {
      case 'scene-spec':
        return VisualGenerationRoute.sceneSpec;
      case 'html-fallback':
        return VisualGenerationRoute.htmlFallback;
      default:
        return null;
    }
  }

  static String _formatGenerationErrorPayload(Map<String, dynamic> payload) {
    final errorType = payload['errorType'] as String?;
    final error =
        payload['error'] as String? ?? 'AI returned no usable visual.';
    final rawText = payload['rawText'] as String?;
    final details = payload['details'];

    final buffer = StringBuffer();
    if (errorType == 'empty-response') {
      buffer.writeln('The model returned an empty generation result.');
    } else if (errorType == 'scene-spec-and-html-failed') {
      buffer.writeln(
        'Scene-spec generation failed, and HTML fallback did not produce a usable visual.',
      );
    } else {
      buffer.writeln(error);
    }

    if (details is Map && details['sceneSpecValidationErrors'] is List) {
      final errors = (details['sceneSpecValidationErrors'] as List)
          .map((value) => value.toString())
          .where((value) => value.trim().isNotEmpty)
          .toList();
      if (errors.isNotEmpty) {
        buffer.writeln();
        buffer.writeln('Scene-spec validation errors:');
        for (final item in errors) {
          buffer.writeln('- $item');
        }
      }
    }

    if (details is Map && details['htmlFallbackError'] is String) {
      buffer.writeln();
      buffer.writeln('HTML fallback error: ${details['htmlFallbackError']}');
    }

    if (rawText != null && rawText.trim().isNotEmpty) {
      final preview = rawText.substring(0, rawText.length.clamp(0, 240));
      buffer.writeln();
      buffer.writeln('Raw response preview: $preview');
    }

    return buffer.toString().trim();
  }
}

