   361→  /// Load lesson titles for a single course (async, cached).
   362→  Future<void> _loadCourseLessons(String courseId) async {
   363→    if (_courseLessons.containsKey(courseId) ||
   364→        _courseLessonLoading.contains(courseId)) {
   365→      return;
   366→    }
   367→    _courseLessonLoading.add(courseId);
   368→    try {
   369→      final titles = await SupabaseService.getCourseLessonTitles(courseId);
   370→      if (mounted) {
   371→        setState(() {
   372→          _courseLessons[courseId] = titles;
   373→          _courseLessonLoading.remove(courseId);
   374→        });
   375→      } else {
   376→        _courseLessonLoading.remove(courseId);
   377→      }
   378→    } catch (_) {
   379→      if (mounted) {
   380→        setState(() {
   381→          _courseLessons[courseId] = [];
   382→          _courseLessonLoading.remove(courseId);
   383→        });
   384→      } else {
   385→        _courseLessonLoading.remove(courseId);
   386→      }
   387→    }
   388→  }
