            hintText: _tr(
              '描述你想生成的动画...',
              'Describe the animation you want to generate...',
            ),
            border: const OutlineInputBorder(),
          ),
          style: const TextStyle(fontSize: AppFontSize.sm),
        ),
        const SizedBox(height: AppSpacing.sm),
        SizedBox(
