          child: FilledButton.icon(
            onPressed: _isGenerating ? null : () => _generate(),
            icon: _isGenerating
                ? const SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: Colors.white,
                    ),
                  )
                : const Icon(Icons.auto_awesome, size: 16),
            label: Text(
              _isGenerating
                  ? _tr('生成中...', 'Generating...')
