              const SizedBox(height: AppSpacing.sm),
            ],

            // Generate / Regenerate button
            SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                onPressed: (_isGenerating || _selectedStyle == null)
                    ? null
                    : _generate,
                icon: _isGenerating
                    ? const SizedBox(
                        width: 14,
                        height: 14,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: Colors.white,
