  void _applySortOrder() {
    setState(() {
      switch (_sortOrder) {
        case 'student':
          // No real student data yet, keep current order
          break;
        case 'comments':
          // No real comments data yet, keep current order
          break;
        default:
          _courses.sort(
            (a, b) => (b['updated_at'] as String? ?? '').compareTo(
              a['updated_at'] as String? ?? '',
