}

// ─── Thumbnail mode toggle chip ────────────────────────────────────────────
class _ThumbnailModeChip extends StatelessWidget {
  final String label;
  final IconData icon;
  final bool active;
  final VoidCallback onTap;

  const _ThumbnailModeChip({
    required this.label,
    required this.icon,
    required this.active,
