import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import { FormField, Textarea } from '../FormField';
import type { Block } from '@primoria/schema';

const schema = z.object({
  // Store plain text for editing; persisted as richtext ops
  plainText: z.string(),
});

type FormValues = z.infer<typeof schema>;

interface TextPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

function opsToPlain(ops: Array<{ insert?: string }>): string {
  return ops.map((o) => (typeof o.insert === 'string' ? o.insert : '')).join('');
}

function plainToOps(text: string): Array<{ insert: string }> {
  return [{ insert: text || '\n' }];
}

export function TextPanel({ block, lessonId, pageId }: TextPanelProps) {
  const dispatch = useAppDispatch();
  const c = block.content as { value?: { ops?: Array<{ insert?: string }> } };
  const initial = opsToPlain(c.value?.ops ?? []);

  const { register, watch, reset } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { plainText: initial },
  });

  // Reset form when selected block changes
  useEffect(() => {
    reset({ plainText: opsToPlain(c.value?.ops ?? []) });
  }, [block.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Live sync to Redux store
  useEffect(() => {
    const sub = watch((values) => {
      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: {
            ...block,
            content: {
              format: 'richtext',
              value: { ops: plainToOps(values.plainText ?? '') },
            },
          },
        }),
      );
    });
    return () => sub.unsubscribe();
  }, [watch, block, lessonId, pageId, dispatch]);

  return (
    <div className="space-y-4">
      <FormField label="Content">
        <Textarea rows={6} {...register('plainText')} placeholder="Enter text…" />
      </FormField>
      <p className="text-xs text-muted-foreground">
        Rich text editor (TipTap) coming in Phase 3.
      </p>
    </div>
  );
}

