import { useState } from 'react';
import { PlusIcon, Pencil1Icon, CheckIcon } from '@radix-ui/react-icons';
import { useAppDispatch, useAppSelector } from '@/store';
import { addBlock, markDirty } from '@/store/editorSlice';
import { nanoid } from '@/lib/nanoid';
import { cn } from '@/lib/utils';

interface LessonNavProps {
  selectedLessonId: string | null;
  selectedPageId: string | null;
  onSelectLesson: (lessonId: string, pageId: string) => void;
}

export function LessonNav({ selectedLessonId, selectedPageId, onSelectLesson }: LessonNavProps) {
  const dispatch = useAppDispatch();
  const draft = useAppSelector((s) => s.editor.draft);

  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');

  if (!draft) return null;

  function handleAddLesson() {
    if (!draft) return;
    const lessonId = nanoid();
    const pageId = `page-${lessonId}-0`;

    // We mutate through Redux — need to add a lesson-level action
    // For now, add a placeholder block so the lesson/page is "reachable"
    // Full lesson-add action can come in Phase 3 when we add the lessons slice
    dispatch(
      addBlock({
        lessonId,
        pageId,
        block: {
          id: nanoid(),
          type: 'text',
          position: { order: 0 },
          content: { format: 'richtext', value: { ops: [{ insert: '\n' }] } },
        },
      }),
    );
    // Note: addBlock guards on lessonId/pageId existing in draft — new lessons need
    // to be added at draft level. Phase 3 will add addLesson/addPage Redux actions.
    // For now dispatch markDirty to show intent.
    dispatch(markDirty());
  }

  return (
    <div className="h-full overflow-y-auto border-r bg-muted/30">
      <div className="px-3 py-3 flex items-center justify-between border-b">
        <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
          Lessons
        </span>
        <button
          onClick={handleAddLesson}
          className="p-1 rounded hover:bg-accent transition-colors text-muted-foreground hover:text-foreground"
          title="Add lesson (Phase 3)"
        >
          <PlusIcon className="h-3.5 w-3.5" />
        </button>
      </div>

      <div className="p-2 space-y-1">
        {draft.lessons.map((lesson, li) => (
          <div key={lesson.lesson_id}>
            {/* Lesson header */}
            <div
              className={cn(
                'flex items-center gap-1.5 rounded-md px-2 py-1.5 cursor-pointer',
                'hover:bg-accent transition-colors group',
                selectedLessonId === lesson.lesson_id && 'bg-accent',
              )}
              onClick={() => {
                const firstPage = lesson.pages[0];
                if (firstPage) onSelectLesson(lesson.lesson_id, firstPage.page_id);
              }}
            >
              {editingLessonId === lesson.lesson_id ? (
                <>
                  <input
                    autoFocus
                    value={editTitle}
                    onChange={(e) => setEditTitle(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === 'Escape') setEditingLessonId(null);
                    }}
                    className="flex-1 text-xs bg-transparent outline-none border-b border-primary"
                    onClick={(e) => e.stopPropagation()}
                  />
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setEditingLessonId(null);
                      dispatch(markDirty());
                    }}
                    className="text-primary"
                  >
                    <CheckIcon className="h-3 w-3" />
                  </button>
                </>
              ) : (
                <>
                  <span className="text-xs text-muted-foreground w-4 shrink-0">
                    {li + 1}
                  </span>
                  <span className="flex-1 text-sm truncate">{lesson.title}</span>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setEditingLessonId(lesson.lesson_id);
                      setEditTitle(lesson.title);
                    }}
                    className="opacity-0 group-hover:opacity-100 p-0.5 rounded hover:bg-background transition-all"
                  >
                    <Pencil1Icon className="h-3 w-3 text-muted-foreground" />
                  </button>
                </>
              )}
            </div>

            {/* Pages */}
            {lesson.pages.length > 1 && selectedLessonId === lesson.lesson_id && (
              <div className="ml-4 mt-1 space-y-0.5">
                {lesson.pages.map((page, pi) => (
                  <button
                    key={page.page_id}
                    onClick={() => onSelectLesson(lesson.lesson_id, page.page_id)}
                    className={cn(
                      'w-full text-left rounded px-2 py-1 text-xs transition-colors',
                      selectedPageId === page.page_id
                        ? 'bg-primary/10 text-primary font-medium'
                        : 'text-muted-foreground hover:bg-accent',
                    )}
                  >
                    Page {pi + 1}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

