  function handleLanguageChange(e: React.ChangeEvent<HTMLSelectElement>) {
    dispatch(
      updateBlock({
        lessonId,
        pageId,
        block: { ...block, content: { ...c, language: e.target.value } },
      }),
    );
  }

  return (
    <div className="space-y-3">
      <FormField label="Language">
        <Select value={language} onChange={handleLanguageChange}>
          {LANGUAGES.map((l) => (
            <option key={l.value} value={l.value}>
              {l.label}
            </option>
          ))}
        </Select>
      </FormField>

      <div className="space-y-1">
        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
          Code
        </div>
        <div className="overflow-hidden rounded-md border text-sm">
          <CodeMirror
            value={code}
            extensions={extensions}
            theme={oneDark}
            onChange={handleCodeChange}
            minHeight="120px"
            maxHeight="400px"
            basicSetup={{
              lineNumbers: true,
              foldGutter: true,
              autocompletion: true,
              bracketMatching: true,
            }}
          />
        </div>
      </div>

      {block.type === 'code-playground' && (
        <p className="text-xs text-muted-foreground">
          This is starter code. Learners will be able to edit and run it.
        </p>
      )}
      {block.type === 'code-block' && (
        <label className="flex items-center gap-2 text-sm cursor-pointer">
          <input
            type="checkbox"
            checked={c.showLineNumbers ?? true}
            onChange={(e) =>
              dispatch(
                updateBlock({
                  lessonId,
                  pageId,
                  block: { ...block, content: { ...c, showLineNumbers: e.target.checked } },
                }),
              )
            }
            className="h-4 w-4"
          />
          Show line numbers
        </label>
      )}
    </div>
  );
}

