import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import { FormField, Select, Textarea } from '../FormField';
import type { Block } from '@primoria/schema';

const LANGUAGES = ['python', 'javascript', 'typescript', 'java', 'c', 'cpp', 'rust', 'go', 'sql'];

const schema = z.object({
  language: z.string().min(1),
  code: z.string(),
});

type FormValues = z.infer<typeof schema>;

interface CodeBlockPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

export function CodeBlockPanel({ block, lessonId, pageId }: CodeBlockPanelProps) {
  const dispatch = useAppDispatch();
  const c = block.content as { language?: string; code?: string; starterCode?: string };

  const { register, watch, reset } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      language: c.language ?? 'python',
      code: c.code ?? c.starterCode ?? '',
    },
  });

  useEffect(() => {
    reset({ language: c.language ?? 'python', code: c.code ?? c.starterCode ?? '' });
  }, [block.id]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const sub = watch((values) => {
      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: {
            ...block,
            content: {
              ...(block.content as object),
              language: values.language,
              code: values.code,
              starterCode: values.code, // keep both keys in sync for playground
            },
          },
        }),
      );
    });
    return () => sub.unsubscribe();
  }, [watch, block, lessonId, pageId, dispatch]);

  return (
    <div className="space-y-4">
      <FormField label="Language">
        <Select {...register('language')}>
          {LANGUAGES.map((l) => (
            <option key={l} value={l}>
              {l}
            </option>
          ))}
        </Select>
      </FormField>
      <FormField label="Code">
        <Textarea rows={10} {...register('code')} placeholder="// code here" className="font-mono text-xs" />
      </FormField>
    </div>
  );
}

