              <TrashIcon className="h-3.5 w-3.5" />
            </button>
          </div>
        ))}

        {fields.length === 0 && (
          <p className="text-xs text-muted-foreground">Add pairs for learners to match.</p>
        )}
      </div>
    </div>
  );
}

