import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import { FormField, Input, Select, Textarea } from '../FormField';
import type { Block } from '@primoria/schema';

const PRESETS = [
  { value: '', label: '(none — use AI prompt)' },
  { value: 'bubble-sort', label: 'Bubble Sort' },
  { value: 'merge-sort', label: 'Merge Sort' },
  { value: 'binary-search', label: 'Binary Search' },
  { value: 'linked-list', label: 'Linked List' },
  { value: 'bfs', label: 'BFS / DFS' },
  { value: 'stack-queue', label: 'Stack & Queue' },
  { value: 'dijkstra', label: "Dijkstra's Algorithm" },
];

const schema = z.object({
  preset: z.string().optional(),
  aiPrompt: z.string().optional(),
  customHtml: z.string().optional(),
});

type FormValues = z.infer<typeof schema>;

interface AnimationPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

export function AnimationPanel({ block, lessonId, pageId }: AnimationPanelProps) {
  const dispatch = useAppDispatch();
  const c = block.content as {
    preset?: string;
    aiPrompt?: string;
    customHtml?: string;
  };

  const { register, watch, reset } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      preset: c.preset ?? '',
      aiPrompt: c.aiPrompt ?? '',
      customHtml: c.customHtml ?? '',
    },
  });

  useEffect(() => {
    reset({ preset: c.preset ?? '', aiPrompt: c.aiPrompt ?? '', customHtml: c.customHtml ?? '' });
  }, [block.id]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const sub = watch((values) => {
      dispatch(updateBlock({ lessonId, pageId, block: { ...block, content: values } }));
    });
    return () => sub.unsubscribe();
  }, [watch, block, lessonId, pageId, dispatch]);

  return (
    <div className="space-y-4">
      <FormField label="Preset animation">
        <Select {...register('preset')}>
          {PRESETS.map((p) => (
            <option key={p.value} value={p.value}>
              {p.label}
            </option>
          ))}
        </Select>
      </FormField>

      <FormField label="AI prompt (optional)">
        <Textarea
          rows={3}
          {...register('aiPrompt')}
          placeholder="Describe the animation you want…"
        />
        <p className="text-xs text-muted-foreground mt-1">
          Leave blank to use the preset, or write a prompt to generate a custom animation.
        </p>
      </FormField>

      <FormField label="Custom HTML (advanced)">
        <Textarea
          rows={5}
          {...register('customHtml')}
          placeholder="<canvas id='c'></canvas><script>…</script>"
          className="font-mono text-xs"
        />
      </FormField>
    </div>
  );
}

import { useCallback, useMemo } from 'react';
import CodeMirror from '@uiw/react-codemirror';
import { oneDark } from '@codemirror/theme-one-dark';
import { python } from '@codemirror/lang-python';
import { javascript } from '@codemirror/lang-javascript';
import { java } from '@codemirror/lang-java';
import { rust } from '@codemirror/lang-rust';
import { sql } from '@codemirror/lang-sql';
import type { Extension } from '@codemirror/state';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import { FormField, Select } from '../FormField';
import type { Block } from '@primoria/schema';

const LANGUAGES: Array<{ value: string; label: string; ext: () => Extension }> = [
  { value: 'python', label: 'Python', ext: () => python() },
  { value: 'javascript', label: 'JavaScript', ext: () => javascript() },
  { value: 'typescript', label: 'TypeScript', ext: () => javascript({ typescript: true }) },
  { value: 'java', label: 'Java', ext: () => java() },
  { value: 'rust', label: 'Rust', ext: () => rust() },
  { value: 'sql', label: 'SQL', ext: () => sql() },
  { value: 'c', label: 'C / C++', ext: () => [] as unknown as Extension },
  { value: 'go', label: 'Go', ext: () => [] as unknown as Extension },
];

interface CodeBlockPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

export function CodeBlockPanel({ block, lessonId, pageId }: CodeBlockPanelProps) {
  const dispatch = useAppDispatch();
  const c = block.content as {
    language?: string;
    code?: string;
    starterCode?: string;
    showLineNumbers?: boolean;
  };

  const language = c.language ?? 'python';
  const code = c.code ?? c.starterCode ?? '';

  const langEntry = LANGUAGES.find((l) => l.value === language) ?? LANGUAGES[0];
  const extensions = useMemo(() => [langEntry!.ext()], [language]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleCodeChange = useCallback(
    (value: string) => {
      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: {
            ...block,
            content: { ...c, code: value, starterCode: value },
          },
        }),
      );
    },
    [dispatch, block, lessonId, pageId, c],
  );

  function handleLanguageChange(e: React.ChangeEvent<HTMLSelectElement>) {
    dispatch(
      updateBlock({
        lessonId,
        pageId,
        block: { ...block, content: { ...c, language: e.target.value } },
      }),
    );
  }

  return (
    <div className="space-y-3">
      <FormField label="Language">
        <Select value={language} onChange={handleLanguageChange}>
          {LANGUAGES.map((l) => (
            <option key={l.value} value={l.value}>
              {l.label}
            </option>
          ))}
        </Select>
      </FormField>

      <div className="space-y-1">
        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
          Code
        </div>
        <div className="overflow-hidden rounded-md border text-sm">
          <CodeMirror
            value={code}
            extensions={extensions}
            theme={oneDark}
            onChange={handleCodeChange}
            minHeight="120px"
            maxHeight="400px"
            basicSetup={{
              lineNumbers: true,
              foldGutter: true,
              autocompletion: true,
              bracketMatching: true,
            }}
          />
        </div>
      </div>

      {block.type === 'code-playground' && (
        <p className="text-xs text-muted-foreground">
          This is starter code. Learners will be able to edit and run it.
        </p>
      )}
      {block.type === 'code-block' && (
        <label className="flex items-center gap-2 text-sm cursor-pointer">
          <input
            type="checkbox"
            checked={c.showLineNumbers ?? true}
            onChange={(e) =>
              dispatch(
                updateBlock({
                  lessonId,
                  pageId,
                  block: { ...block, content: { ...c, showLineNumbers: e.target.checked } },
                }),
              )
            }
            className="h-4 w-4"
          />
          Show line numbers
        </label>
      )}
    </div>
  );
}

import { useEffect } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Placeholder from '@tiptap/extension-placeholder';
import { useAppDispatch } from '@/store';
import { updateBlock } from '@/store/editorSlice';
import type { Block } from '@primoria/schema';

// ─── Richtext ↔ JSON ──────────────────────────────────────────────────────────

type RichtextOp = { insert: string; attributes?: Record<string, unknown> };
type RichtextValue = { ops: RichtextOp[] };

/** Convert Quill-style ops to plain text (lossy — preserves line breaks only). */
function opsToText(ops: RichtextOp[]): string {
  return ops.map((o) => o.insert).join('');
}

/** Wrap plain text back in ops format. */
function textToOps(text: string): RichtextOp[] {
  if (!text) return [{ insert: '\n' }];
  return text.split('\n').flatMap((line, i, arr) =>
    i < arr.length - 1 ? [{ insert: line }, { insert: '\n' }] : [{ insert: line }],
  );
}

// ─── Component ────────────────────────────────────────────────────────────────

interface TextPanelProps {
  block: Block;
  lessonId: string;
  pageId: string;
}

export function TextPanel({ block, lessonId, pageId }: TextPanelProps) {
  const dispatch = useAppDispatch();
  const c = block.content as { value?: { ops?: RichtextOp[] } };
  const initialText = opsToText(c.value?.ops ?? [{ insert: '\n' }]);

  const editor = useEditor({
    extensions: [
      StarterKit,
      Placeholder.configure({ placeholder: 'Start typing…' }),
    ],
    content: initialText,
    onUpdate({ editor: e }) {
      const text = e.getText();
      dispatch(
        updateBlock({
          lessonId,
          pageId,
          block: {
            ...block,
            content: {
              format: 'richtext',
              value: { ops: textToOps(text) },
            },
          },
        }),
      );
    },
  });

  // Reinitialise when a different block is selected
  useEffect(() => {
    if (!editor) return;
    const fresh = opsToText(c.value?.ops ?? [{ insert: '\n' }]);
    if (editor.getText() !== fresh) {
      editor.commands.setContent(fresh);
    }
  }, [block.id]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="space-y-3">
      {/* Formatting toolbar */}
      {editor && (
        <div className="flex flex-wrap gap-1 border-b pb-2">
          {[
            { label: 'B', title: 'Bold', cmd: () => editor.chain().focus().toggleBold().run(), active: editor.isActive('bold') },
            { label: 'I', title: 'Italic', cmd: () => editor.chain().focus().toggleItalic().run(), active: editor.isActive('italic') },
            { label: 'S', title: 'Strike', cmd: () => editor.chain().focus().toggleStrike().run(), active: editor.isActive('strike') },
            { label: 'H1', title: 'Heading 1', cmd: () => editor.chain().focus().toggleHeading({ level: 1 }).run(), active: editor.isActive('heading', { level: 1 }) },
            { label: 'H2', title: 'Heading 2', cmd: () => editor.chain().focus().toggleHeading({ level: 2 }).run(), active: editor.isActive('heading', { level: 2 }) },
            { label: '•', title: 'Bullet list', cmd: () => editor.chain().focus().toggleBulletList().run(), active: editor.isActive('bulletList') },
            { label: '1.', title: 'Ordered list', cmd: () => editor.chain().focus().toggleOrderedList().run(), active: editor.isActive('orderedList') },
            { label: '—', title: 'Code block', cmd: () => editor.chain().focus().toggleCodeBlock().run(), active: editor.isActive('codeBlock') },
          ].map(({ label, title, cmd, active }) => (
            <button
              key={title}
              type="button"
              title={title}
              onClick={cmd}
              className={`px-2 py-0.5 rounded text-xs font-mono transition-colors ${
                active
                  ? 'bg-primary text-primary-foreground'
                  : 'border hover:bg-accent'
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      )}

      <EditorContent
        editor={editor}
        className="prose prose-sm max-w-none min-h-[120px] rounded-md border p-3 text-sm focus-within:ring-2 focus-within:ring-ring [&_.tiptap]:outline-none [&_.tiptap_p.is-editor-empty:first-child::before]:text-muted-foreground [&_.tiptap_p.is-editor-empty:first-child::before]:content-[attr(data-placeholder)] [&_.tiptap_p.is-editor-empty:first-child::before]:float-left [&_.tiptap_p.is-editor-empty:first-child::before]:pointer-events-none"
      />
    </div>
  );
}

