      >
        <ResetIcon className="h-4 w-4" />
      </button>
      <button
        onClick={() => dispatch(redo())}
        disabled={!canRedo}
        title="Redo (⌘⇧Z)"
        className="p-1.5 rounded hover:bg-accent disabled:opacity-30 transition-colors scale-x-[-1]"
      >
        <ResetIcon className="h-4 w-4" />
      </button>

      <div className="w-px h-5 bg-border" />

